// ==========================================================================
// BACKGROUND CLOCK
// A hidden tab gets its setTimeout/setInterval clamped to once a second, and
// after a few minutes to once a minute, so auto-spin used to crawl whenever the
// page was minimised. The spin loop's timers run in a tiny worker instead
// (worker timers aren't throttled like that), and while the page is hidden the
// purely visual parts (flying preview cards, drop cinematics) are skipped, so
// spins keep exactly the same pace. Falls back to normal timers if workers fail.
// ==========================================================================
const BGClock = (function(){
  let worker = null, seq = 0;
  const fns = new Map();
  try{
    const src = "const T=new Map();onmessage=function(e){var d=e.data;if(d.c==='t'){T.set(d.id,setTimeout(function(){T.delete(d.id);postMessage(d.id);},d.ms));}else if(d.c==='i'){T.set(d.id,setInterval(function(){postMessage(d.id);},d.ms));}else if(d.c==='x'){var h=T.get(d.id);clearTimeout(h);clearInterval(h);T.delete(d.id);}};";
    worker = new Worker(URL.createObjectURL(new Blob([src], { type:'text/javascript' })));
    worker.onmessage = (e)=>{
      const f = fns.get(e.data);
      if(!f) return;
      if(!f.repeat) fns.delete(e.data);
      try{ f.fn(); }catch(err){ console.error(err); }
    };
    worker.onerror = ()=>{ worker = null; };
  }catch(e){ worker = null; }
  return {
    timeout(fn, ms){
      if(!worker) return setTimeout(fn, ms);
      const id = ++seq; fns.set(id, { fn, repeat:false }); worker.postMessage({ c:'t', id, ms: ms || 0 }); return 'bg' + id;
    },
    interval(fn, ms){
      if(!worker) return setInterval(fn, ms);
      const id = ++seq; fns.set(id, { fn, repeat:true }); worker.postMessage({ c:'i', id, ms }); return 'bg' + id;
    },
    clear(h){
      if(h == null) return;
      if(typeof h === 'string' && h.startsWith('bg')){ const id = Number(h.slice(2)); fns.delete(id); if(worker) worker.postMessage({ c:'x', id }); }
      else { clearTimeout(h); clearInterval(h); }
    },
    wait(ms){ return new Promise(r=> this.timeout(r, ms)); }
  };
})();
