 // Auto-spin config
 // Auto-unlock is performed automatically once totalSpins >= 200; no purchase available.
 const AUTO_UNLOCK_PRICE = null;
 let autoSpinUnlocked = false;
 let autoSpinEnabled = false;
 let autoSpinCheckerId = null;

 // shared spin state to prevent overlapping spins from clicks and spacebar
 let isSpinning = false;

function updateAutoSpinButton(){
  if(!autoSpinBtn) return;
  // free unlock when user has reached 200 total spins — this only makes the button
  // usable, it does NOT start spinning by itself; the player still has to press it.
  if(!autoSpinUnlocked && typeof totalSpins === 'number' && totalSpins >= 200){
    autoSpinUnlocked = true;
  }

  if(!autoSpinUnlocked){
    // closed state (no purchase option shown)
    autoSpinBtn.innerHTML = '<span class="as-led as-lock" aria-hidden="true"></span>Авто‑Прокрутка';
    autoSpinBtn.style.background = '#b8860b';
    autoSpinBtn.setAttribute('aria-pressed','false');
  } else {
    autoSpinBtn.innerHTML = '<span class="as-led" aria-hidden="true"></span>' + (autoSpinEnabled ? 'Авто‑Прокрутка: Вкл' : 'Авто‑Прокрутка: Выкл');
    autoSpinBtn.style.background = autoSpinEnabled ? '#0b6623' : '#777';
    autoSpinBtn.setAttribute('aria-pressed', String(!!autoSpinEnabled));
  }
}

 // toggle/attempt-unlock handler
if(autoSpinBtn){
  autoSpinBtn.addEventListener('click', ()=>{
    // if not unlocked yet, allow free unlock when totalSpins >= 200
      if(!autoSpinUnlocked){
      // Only unlocks automatically once the player has reached 200 total spins.
      if(typeof totalSpins === 'number' && totalSpins >= 200){
        autoSpinUnlocked = true;
        autoSpinEnabled = false;
        updateAutoSpinButton();
        briefResultMessage('Авто‑Прокрутка разблокирована бесплатно (200 прокруток)');
        return;
      }
      window.alert('Авто‑Прокрутка разблокируется автоматически при достижении 200 прокруток.');
      return;
    }
    // already unlocked -> toggle enabled state
    autoSpinEnabled = !autoSpinEnabled;
    updateAutoSpinButton();
    briefResultMessage(autoSpinEnabled ? 'Авто‑Прокрутка включена' : 'Авто‑Прокрутка выключена');

    // when enabling, start checker that triggers spins as soon as spinBtn is available
    if(autoSpinEnabled){
      if(autoSpinCheckerId) BGClock.clear(autoSpinCheckerId);
      autoSpinCheckerId = BGClock.interval(()=>{
        if(autoSpinEnabled && !spinBtn.disabled){
          // prevent overlapping calls: showPreviewsThenReveal will disable spinBtn
          showPreviewsThenReveal();
        }
      }, 300);
    } else {
      if(autoSpinCheckerId){ BGClock.clear(autoSpinCheckerId); autoSpinCheckerId = null; }
    }
  });
}

