// helper to give an item to inventory or potions (defaults to +1)
function giveDevItem(id, qty = 1){
  if(!id) return false;
  qty = Math.max(1, Math.floor(Number(qty) || 1));
  if(POTIONS[id]){
    POTIONS[id].count = (POTIONS[id].count || 0) + qty;
    renderInventory();
    return true;
  }
  if(!ITEMS[id]) return false;
  ensureItem(id);
  inventory[id].count += qty;
  inventory[id].times += qty;
  recordPulls(id, qty);
  // dev-given counts as "had in inventory" for the filter list
  try{
    if(typeof window._seenItems === 'undefined') window._seenItems = {};
    window._seenItems[id] = true;
  }catch(e){}
  renderInventory();
  return true;
}

const ADM = (function(){
  const WEATHERS = [
    { name:'Обычная',       chance:'≈29%',     dur:()=>WEATHER_DEFAULT_DURATION, color:'#7a8a80' },
    { name:'Дождь',         chance:'24.75%',   dur:()=>RAIN_DURATION,            color:'#2f6fd0' },
    { name:'Ветреная',      chance:'25%',      dur:()=>WINDY_DURATION,           color:'#3fa79a' },
    { name:'Снежная',       chance:'20%',      dur:()=>WEATHER_DEFAULT_DURATION, color:'#5aa6d6' },
    { name:'Каловый дождь', chance:'1%',       dur:()=>POOP_RAIN_DURATION,       color:'#8b5a2b' },
    { name:'Kawaii',        chance:'0.2%',     dur:()=>KAWAII_DURATION,          color:'#e2559a' },
    { name:'Матрица',       chance:'1 к 5 555', dur:()=>MATRIX_DURATION,          color:'#1f9d4a' }
  ];
  const CLASS_ORDER = ['common','weak','decent','normal','good','very_good','super','incredible','special'];
  const st = { sec:'give', kind:'auras', cls:'all', q:'', qty:1 };
  let built = false, tickId = null, toastTimer = null;
  let root, lockEl, codeInput, codeErr, contentEl, statsEl, toastEl, navBtns = {};
  const secs = {};

  // tiny DOM helper: h('div.cls#id', {attrs}, ...children)
  function h(sel, attrs, ...kids){
    const m = sel.match(/^([a-z0-9]+)?((?:[.#][\w-]+)*)$/i);
    const el = document.createElement((m && m[1]) || 'div');
    if(m && m[2]) m[2].replace(/([.#])([\w-]+)/g, (_, t, v)=>{ if(t === '.') el.classList.add(v); else el.id = v; });
    if(attrs) for(const k in attrs){
      const v = attrs[k];
      if(v === undefined || v === null || v === false) continue;
      if(k === 'html') el.innerHTML = v;
      else if(k === 'text') el.textContent = v;
      else if(k.startsWith('on')) el.addEventListener(k.slice(2), v);
      else if(k === 'style' && typeof v === 'object'){ for(const p in v){ if(p.startsWith('--')) el.style.setProperty(p, v[p]); else el.style[p] = v[p]; } }
      else el.setAttribute(k, v === true ? '' : v);
    }
    kids.flat().forEach(c=>{ if(c === null || c === undefined || c === false) return; el.appendChild(typeof c === 'string' ? document.createTextNode(c) : c); });
    return el;
  }
  const fmt = n => String(Math.floor(Number(n) || 0)).replace(/\B(?=(\d{3})+(?!\d))/g, ' ');
  const esc = s => String(s == null ? '' : s).replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
  const mmss = ms => { const s = Math.max(0, Math.round((ms || 0) / 1000)); return Math.floor(s / 60) + ':' + String(s % 60).padStart(2, '0'); };

  function toast(msg, kind){
    if(!toastEl) return;
    toastEl.textContent = msg;
    toastEl.className = 'adm-toast show' + (kind ? ' ' + kind : '');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(()=>{ toastEl.className = 'adm-toast'; }, kind === 'err' ? 2600 : 1600);
  }
  function numIn(placeholder, extra){ return h('input.adm-in', Object.assign({ type:'number', inputmode:'decimal', placeholder }, extra || {})); }
  function btn(label, onclick, cls){ return h('button.adm-btn' + (cls ? '.' + cls : ''), { type:'button', onclick }, label); }
  function card(title, sub, ...body){
    return h('section.adm-card', null, h('header.adm-card-h', null, h('h3', { text:title }), sub ? h('p', { text:sub }) : null), ...body);
  }
  function copyText(input){
    const v = input.value;
    if(!v){ toast('Сначала сгенерируй код', 'err'); return; }
    const done = ()=> toast('Код скопирован');
    try{
      if(navigator.clipboard && navigator.clipboard.writeText){ navigator.clipboard.writeText(v).then(done, ()=>{ input.select(); document.execCommand('copy'); done(); }); return; }
    }catch(e){}
    input.select(); try{ document.execCommand('copy'); }catch(e){} done();
  }

  // ---------- shell ----------
  function buildShell(){
    devPanel.innerHTML = '';
    devPanel.setAttribute('role', 'dialog');
    devPanel.setAttribute('aria-label', 'Админ-панель');
    root = h('div.adm-shell');
    // lock screen
    codeInput = h('input.adm-in.adm-code#dev-code', { type:'password', autocomplete:'off', placeholder:'Код доступа', 'aria-label':'Код доступа',
      onkeydown:e=>{ if(e.key === 'Enter') tryUnlock(); } });
    codeErr = h('div.adm-code-err#dev-error', { role:'status', 'aria-live':'polite' });
    lockEl = h('div.adm-lock', null,
      h('form.adm-lock-card', { onsubmit:e=>{ e.preventDefault(); tryUnlock(); } },
        h('div.adm-lock-mark', { 'aria-hidden':'true', text:'☰' }),
        h('h2', { text:'Админ-панель' }),
        h('p', { text:'Введи код, чтобы открыть инструменты. После ввода панель остаётся открытой до перезагрузки страницы.' }),
        h('div.adm-row', null, codeInput, h('button.adm-btn.primary#dev-unlock', { type:'submit' }, 'Открыть')),
        codeErr,
        h('button.adm-btn.ghost.adm-lock-close', { type:'button', onclick:close }, 'Закрыть')
      )
    );
    root.appendChild(lockEl);
    devPanel.appendChild(root);
  }

  function buildConsole(){
    if(built) return;
    built = true;
    const rail = h('aside.adm-rail');
    rail.appendChild(h('div.adm-brand', null, h('span.adm-brand-mark', { 'aria-hidden':'true', text:'☰' }), h('div', null, h('b', { text:'Админ-панель' }), h('small', { text:'TURTLE\'S RNG' }))));
    const nav = h('nav.adm-nav', { 'aria-label':'Разделы' });
    [['give','Выдача','Ауры, зелья, снаряжение'],['player','Игрок','Монеты, прокрутки, сохранение'],['world','Мир','Погода и время суток'],['codes','Коды','Слова и промокоды'],['music','Музыка','Все саундтреки тем'],['tests','Проверка','Темы и анимации выпадения']].forEach(([id, label, hint], i)=>{
      const b = h('button.adm-nav-btn', { type:'button', 'data-sec':id, onclick:()=>show(id) }, h('span.adm-nav-k', { text:String(i + 1) }), h('span.adm-nav-t', null, h('b', { text:label }), h('small', { text:hint })));
      navBtns[id] = b; nav.appendChild(b);
    });
    rail.appendChild(nav);
    rail.appendChild(h('div.adm-rail-foot', { html:'<span><kbd>1</kbd>–<kbd>6</kbd> разделы</span><span><kbd>/</kbd> поиск</span><span><kbd>Esc</kbd> закрыть</span>' }));

    statsEl = h('div.adm-stats');
    const top = h('header.adm-top', null, statsEl, h('button.adm-close#dev-close', { type:'button', 'aria-label':'Закрыть админ-панель', onclick:close }, '✕'));
    contentEl = h('div.adm-content');
    secs.give = buildGive(); secs.player = buildPlayer(); secs.world = buildWorld(); secs.codes = buildCodes(); secs.music = buildMusic(); secs.tests = buildTests();
    Object.values(secs).forEach(s => contentEl.appendChild(s));
    toastEl = h('div.adm-toast', { role:'status', 'aria-live':'polite' });
    root.appendChild(rail);
    root.appendChild(h('div.adm-main', null, top, contentEl));
    root.appendChild(toastEl);
  }

  function show(id){
    st.sec = id;
    Object.keys(secs).forEach(k => { secs[k].hidden = k !== id; navBtns[k].classList.toggle('on', k === id); });
    if(id === 'give') renderGrid();
    if(id === 'player') refreshPlayer();
    if(id === 'world') refreshWorld();
    if(id === 'music') refreshMusic();
    if(id === 'tests') renderTests();
    contentEl.scrollTop = 0;
  }

  // ---------- live status strip ----------
  function refreshStats(){
    if(!statsEl) return;
    const luck = (document.getElementById('luck-percent') || {}).textContent || '';
    const speed = (document.getElementById('spin-speed') || {}).textContent || '';
    const wEnds = window._weatherEndsAt ? window._weatherEndsAt - Date.now() : weatherRemainingMs;
    const items = [
      ['Монеты', fmt(coins) + ' 🪙'],
      ['Прокрутки', fmt(totalSpins)],
      ['Удача', luck + (window._devLuckOverride ? ' (dev)' : '')],
      ['Скорость', speed + (window._devSpinSeconds ? ' (dev)' : '')],
      ['Погода', currentWeather + ', ещё ' + mmss(wEnds)],
      ['Время', gameTime]
    ];
    if(statsEl.childElementCount !== items.length){
      statsEl.innerHTML = '';
      items.forEach(()=> statsEl.appendChild(h('div.adm-stat', null, h('small'), h('b'))));
    }
    items.forEach(([k, v], i)=>{ const c = statsEl.children[i]; c.children[0].textContent = k; c.children[1].textContent = v; });
  }

  // ---------- Выдача ----------
  let gridEl, countEl, searchIn, clsRow, kindRow, qtyRow, qtyCustom, potionsBar;
  function itemKind(id){
    if(POTIONS[id]) return 'potions';
    const m = ITEMS[id];
    if(!m) return null;
    return m.rarity === '-' ? 'gear' : 'auras';
  }
  function rarityLines(m){
    if(m.dynamicRarity && typeof m.dynamicRarity === 'object'){
      const dr = m.dynamicRarity;
      const base = typeof dr.base === 'number' ? dr.base : (parseCoinsFromRarity(m.rarity) || null);
      const out = [];
      if(m.nativeWeather && typeof dr.clearOverride === 'number'){
        if(base) out.push(`1 к ${fmt(base)} в погоду «${m.nativeWeather}»`);
        if(dr.clearOverride !== base) out.push(`1 к ${fmt(dr.clearOverride)} в другую погоду`);
      } else {
        const day = typeof dr.dayOverride === 'number' ? dr.dayOverride : base;
        const night = typeof dr.nightOverride === 'number' ? dr.nightOverride : base;
        const native = m.nativeTime || (base && base === (day || night) ? 'День' : 'Ночь');
        const nd = base || (native === 'День' ? day : night);
        const ad = nd === day ? night : day;
        if(nd) out.push(`1 к ${fmt(nd)} ${native === 'День' ? 'днём' : 'ночью'}`);
        if(ad && ad !== nd) out.push(`1 к ${fmt(ad)} ${native === 'День' ? 'ночью' : 'днём'}`);
      }
      return out;
    }
    return [m.rarity || ''];
  }
  // names styled in near-white (e.g. «Обычный») would vanish on the white tile
  function readableName(html){
    return html.replace(/color:\s*(#[0-9a-f]{3,8})/i, (all, hex)=>{
      let x = hex.slice(1); if(x.length === 3) x = x.split('').map(c => c + c).join('');
      const r = parseInt(x.slice(0, 2), 16), g = parseInt(x.slice(2, 4), 16), b = parseInt(x.slice(4, 6), 16);
      return (0.2126 * r + 0.7152 * g + 0.0722 * b) / 255 > 0.78 ? 'color:#171a1c' : all;
    });
  }
  function listFor(kind){
    if(kind === 'potions') return Object.keys(POTIONS).filter(k => POTIONS[k]);
    if(kind === 'gear'){
      const ids = Object.keys(ITEMS).filter(k => ITEMS[k] && ITEMS[k].rarity === '-');
      const rank = (k)=>{ const i = CRAFT_DISPLAY_ORDER.indexOf(k); return i === -1 ? 999 : i; };
      return ids.sort((a, b)=> rank(a) - rank(b));
    }
    const ids = Object.keys(ITEMS).filter(k => ITEMS[k] && itemKind(k) === kind );
    ids.sort((a, b)=>{
      const na = getNativeDenominatorForItem(ITEMS[a]) || Infinity, nb = getNativeDenominatorForItem(ITEMS[b]) || Infinity;
      return na === nb ? (ITEMS[a].name || '').localeCompare(ITEMS[b].name || '', 'ru') : na - nb;
    });
    return ids;
  }
  let gearDescs = null;
  function gearDesc(id){
    if(!gearDescs){
      gearDescs = {};
      try{ (window._craftablesCache && window._craftablesCache.length ? window._craftablesCache : buildCraftablesList()).forEach(e=>{ if(e && e.effectDesc) gearDescs[e.id] = e.effectDesc; }); }catch(e){}
    }
    return gearDescs[id] || '';
  }
  function owned(id){
    if(POTIONS[id]) return POTIONS[id].count || 0;
    return (inventory[id] && inventory[id].count) || 0;
  }
  function buildGive(){
    const sec = h('div.adm-sec', { 'data-sec':'give' });
    searchIn = h('input.adm-in.adm-search', { type:'search', placeholder:'Поиск по названию или id', 'aria-label':'Поиск',
      oninput:()=>{ st.q = searchIn.value.trim().toLowerCase(); renderGrid(); },
      onkeydown:e=>{ if(e.key === 'Enter'){ const first = gridEl.querySelector('.adm-give'); if(first) first.click(); } } });
    kindRow = h('div.adm-seg', { role:'tablist' });
    [['auras','Ауры'],['potions','Зелья'],['gear','Снаряжение']].forEach(([k, l])=>{
      kindRow.appendChild(h('button.adm-seg-b', { type:'button', 'data-k':k, onclick:()=>{ st.kind = k; st.cls = 'all'; renderGrid(); } }, l));
    });
    clsRow = h('div.adm-chips');
    clsRow.appendChild(h('button.adm-chip', { type:'button', 'data-c':'all', onclick:()=>{ st.cls = 'all'; renderGrid(); } }, 'Все классы'));
    CLASS_ORDER.forEach(c=>{
      const meta = RARITY_CLASS_META[c];
      clsRow.appendChild(h('button.adm-chip', { type:'button', 'data-c':c, style:{ '--chip':meta.color }, onclick:()=>{ st.cls = c; renderGrid(); } }, c === 'incredible' ? 'Невероятный' : meta.name.charAt(0) + meta.name.slice(1).toLowerCase()));
    });
    qtyRow = h('div.adm-seg.adm-qty', { 'aria-label':'Количество' });
    qtyCustom = numIn('своё', { min:1, class:'adm-in adm-qty-in', oninput:()=>{ const v = Math.floor(Number(qtyCustom.value)); if(v > 0){ st.qty = v; syncQty(true); } } });
    [1, 10, 100, 1000].forEach(n=>{
      qtyRow.appendChild(h('button.adm-seg-b', { type:'button', 'data-q':n, onclick:()=>{ st.qty = n; qtyCustom.value = ''; syncQty(); } }, '×' + fmt(n)));
    });
    qtyRow.appendChild(qtyCustom);
    potionsBar = h('div.adm-inline', null,
      btn('Выдать все зелья ×999 999', ()=>{
        Object.keys(POTIONS).forEach(k => { if(POTIONS[k]) POTIONS[k].count = 999999; });
        renderInventory(); renderGrid(); toast('Все зелья выданы ×999 999');
      }, 'gold'));
    countEl = h('span.adm-count');
    gridEl = h('div.adm-grid');
    gridEl.addEventListener('click', e=>{
      const b = e.target.closest('.adm-give');
      if(!b) return;
      const id = b.dataset.id;
      let qty = st.qty;
      if(itemKind(id) !== 'potions' && qty > 1000){ qty = 1000; toast('Для аур максимум 1 000 за раз', 'err'); }
      if(giveDevItem(id, qty)){
        const meta = POTIONS[id] || ITEMS[id];
        const tile = b.closest('.adm-tile');
        const own = tile && tile.querySelector('.adm-own');
        if(own) own.textContent = 'Есть: ' + fmt(owned(id));
        if(tile){ tile.classList.remove('flash'); void tile.offsetWidth; tile.classList.add('flash'); }
        toast(`Выдано: ${meta.name} ×${fmt(qty)}`);
      }
    });
    sec.appendChild(h('div.adm-sec-h', null, h('h2', { text:'Выдача' }), h('p', { text:'Нажми «Выдать» на карточке. Enter в поиске выдаёт первую найденную.' })));
    sec.appendChild(h('div.adm-toolbar', null, kindRow, searchIn, qtyRow));
    sec.appendChild(h('div.adm-toolbar.adm-toolbar-2', null, clsRow, potionsBar, countEl));
    sec.appendChild(buildBulk());
    sec.appendChild(gridEl);
    return sec;
  }
  // ---- bulk: give every aura at once, or empty a whole part of the inventory ----
  function allAuraIds(){ return Object.keys(ITEMS).filter(k=> itemKind(k) === 'auras' && !ITEMS[k].isKey); }
  function allGearIds(){ return Object.keys(ITEMS).filter(k=> itemKind(k) === 'gear'); }
  function unequipAll(){
    try{ skipperActive = false; }catch(e){}
    Object.keys(window).forEach(k=>{ if(/(Glove|Collector)Active$/.test(k) && typeof window[k] === 'boolean') window[k] = false; });
    allGearIds().forEach(k=>{ if(typeof window[k + 'Active'] === 'boolean') window[k + 'Active'] = false; });
    try{ recomputeEquipmentEffects(); }catch(e){}
    try{ updateAllGloveBuffIcons(); }catch(e){}
    try{ updateBankButtonVisibility(); }catch(e){}
  }
  function afterBulk(msg){ try{ saveState(); }catch(e){} renderInventory(); renderGrid(); refreshStats(); toast(msg); }
  function buildBulk(){
    let withSpecial = false;
    const special = h('label.adm-check', null,
      h('input', { type:'checkbox', onchange:(e)=>{ withSpecial = e.target.checked; } }),
      h('span', { text:'удалять и «Особенные» (обычно их удалить нельзя)' }));
    const giveAll = btn('Выдать себе все ауры', ()=>{
      const n = Math.max(1, Math.min(1000, st.qty || 1));
      const ids = allAuraIds();
      ids.forEach(id=>{
        ensureItem(id);
        inventory[id].count += n; inventory[id].times += n;
        recordPulls(id, n);
        try{ window._seenItems = window._seenItems || {}; window._seenItems[id] = true; }catch(e){}
      });
      // all of them fit: the slot limit grows to hold every distinct aura
      try{ if(distinctSlotsUsed() > inventoryMaxSlots) inventoryMaxSlots = distinctSlotsUsed(); }catch(e){}
      afterBulk(`Выдано ${fmt(ids.length)} аур по ×${fmt(n)}`);
    }, 'gold');
    const delAuras = btn('Удалить все ауры', ()=>{
      if(!window.confirm(withSpecial ? 'Удалить ВСЕ ауры из инвентаря, включая особенные? Это нельзя отменить.' : 'Удалить все ауры из инвентаря (кроме особенных)? Это нельзя отменить.')) return;
      let n = 0;
      allAuraIds().forEach(id=>{
        if(!inventory[id] || !inventory[id].count) return;
        if(!withSpecial && rarityClassKeyFor(id) === 'special') return;
        n += inventory[id].count;
        inventory[id].count = 0; inventory[id].pulls = [];
      });
      try{ if(typeof selectedPulls !== 'undefined') selectedPulls.clear(); }catch(e){}
      afterBulk(`Удалено аур: ${fmt(n)}`);
    }, 'danger');
    const delPotions = btn('Удалить все зелья и предметы', ()=>{
      if(!window.confirm('Удалить все зелья и предметы? Это нельзя отменить.')) return;
      let n = 0;
      Object.keys(POTIONS).forEach(k=>{ if(POTIONS[k] && POTIONS[k].count){ n += POTIONS[k].count; POTIONS[k].count = 0; } });
      Object.keys(ITEMS).forEach(k=>{ if(ITEMS[k].isKey && inventory[k] && inventory[k].count){ n += inventory[k].count; inventory[k].count = 0; inventory[k].pulls = []; } });
      afterBulk(`Удалено зелий и предметов: ${fmt(n)}`);
    }, 'danger');
    const delGear = btn('Удалить всё снаряжение', ()=>{
      if(!window.confirm('Снять и удалить всё снаряжение? Это нельзя отменить.')) return;
      unequipAll();
      let n = 0;
      allGearIds().forEach(id=>{ if(inventory[id] && inventory[id].count){ n += inventory[id].count; inventory[id].count = 0; inventory[id].pulls = []; } });
      afterBulk(`Удалено снаряжения: ${fmt(n)}`);
    }, 'danger');
    return h('div.adm-card.adm-bulk', null,
      h('div.adm-bulk-h', null, h('b', { text:'Весь инвентарь сразу' }), h('span', { text:'«Выдать все ауры» использует выбранное количество (×1, ×10…, до 1 000).' })),
      h('div.adm-row.adm-bulk-row', null, giveAll, delAuras, delPotions, delGear),
      special);
  }
  function syncQty(custom){
    qtyRow.querySelectorAll('[data-q]').forEach(b => b.classList.toggle('on', !custom && Number(b.dataset.q) === st.qty));
    gridEl.querySelectorAll('.adm-give').forEach(b => { b.textContent = '+' + fmt(st.qty); });
  }
  function renderGrid(){
    if(!gridEl) return;
    kindRow.querySelectorAll('[data-k]').forEach(b => b.classList.toggle('on', b.dataset.k === st.kind));
    clsRow.hidden = st.kind !== 'auras';
    potionsBar.hidden = st.kind !== 'potions';
    if(!clsRow._counted){
      clsRow._counted = true;
      const have = new Set(listFor('auras').map(rarityClassKeyFor));
      clsRow.querySelectorAll('[data-c]').forEach(b => { if(b.dataset.c !== 'all' && !have.has(b.dataset.c)) b.hidden = true; });
    }
    clsRow.querySelectorAll('[data-c]').forEach(b => b.classList.toggle('on', b.dataset.c === st.cls));
    const q = st.q;
    const ids = listFor(st.kind).filter(id=>{
      const meta = POTIONS[id] || ITEMS[id];
      if(st.kind === 'auras' && st.cls !== 'all' && rarityClassKeyFor(id) !== st.cls) return false;
      if(!q) return true;
      return (meta.name || '').toLowerCase().includes(q) || id.toLowerCase().includes(q);
    });
    countEl.textContent = ids.length ? `Найдено: ${ids.length}` : '';
    const frag = document.createDocumentFragment();
    ids.forEach(id=>{
      const isPotion = !!POTIONS[id];
      const meta = isPotion ? POTIONS[id] : ITEMS[id];
      const cls = isPotion ? '' : rarityClassCssKeyFor(id);
      const tile = h('div.adm-tile' + (cls ? '.rc-' + cls : ''), { style:{ '--rc': isPotion ? (meta.color || '#2f8a3c') : (RARITY_CLASS_META[rarityClassKeyFor(id)] || {}).color || '#9aa' } });
      const nameHtml = isPotion ? esc(meta.name) : readableName(styledRarityName(id, meta.name, true));
      const lines = isPotion ? [meta.desc || ''] : (meta.rarity === '-' ? [gearDesc(id) || meta.desc || 'Снаряжение'] : rarityLines(meta));
      tile.innerHTML = `<div class="adm-tile-main"><div class="adm-tile-name">${nameHtml}</div>${isPotion || meta.rarity === '-' ? '' : rarityClassBadge(id)}<div class="adm-tile-r">${lines.map(esc).join('<br>')}</div></div>`
        + `<div class="adm-tile-foot"><span class="adm-own">Есть: ${fmt(owned(id))}</span><code>${esc(id)}</code><button type="button" class="adm-give" data-id="${esc(id)}">+${fmt(st.qty)}</button></div>`;
      frag.appendChild(tile);
    });
    gridEl.innerHTML = '';
    if(!ids.length) gridEl.appendChild(h('div.adm-empty', { text: q ? `Ничего не найдено по запросу «${st.q}». Проверь написание или сбрось фильтр класса.` : 'В этой категории пусто.' }));
    else gridEl.appendChild(frag);
    syncQty(!!qtyCustom.value);
  }

  // ---------- Игрок ----------
  let coinNow, spinNow, ovrInfo, luckIn, speedIn, questList;
  function buildPlayer(){
    const sec = h('div.adm-sec', { 'data-sec':'player', hidden:true });
    sec.appendChild(h('div.adm-sec-h', null, h('h2', { text:'Игрок' }), h('p', { text:'Изменения применяются сразу и попадут в автосохранение.' })));
    // coins
    coinNow = h('div.adm-big');
    const coinIn = numIn('Сумма', { min:0 });
    const addCoins = v=>{
      if(!Number.isFinite(v) || v <= 0){ toast('Введи положительное число', 'err'); return; }
      coins += Math.floor(v); updateCoinDisplay(true); refreshPlayer(); toast(`+${fmt(v)} 🪙`);
    };
    const coinCard = card('Монеты', null, coinNow,
      coinIn,
      h('div.adm-row', null,
        btn('Добавить', ()=>{ addCoins(Number(coinIn.value)); coinIn.value = ''; }, 'primary'),
        btn('Установить', ()=>{
          const v = Number(coinIn.value);
          if(coinIn.value === '' || !Number.isFinite(v) || v < 0){ toast('Введи корректную сумму', 'err'); return; }
          coins = Math.max(0, Math.floor(v)); updateCoinDisplay(false); refreshPlayer(); toast(`Монеты: ${fmt(coins)} 🪙`); coinIn.value = '';
        })),
      h('div.adm-row.adm-quick', null, ...[1000, 100000, 1000000, 1000000000].map(n => btn('+' + fmt(n), ()=> addCoins(n), 'soft')))
    );
    coinIn.addEventListener('keydown', e=>{ if(e.key === 'Enter'){ addCoins(Number(coinIn.value)); coinIn.value = ''; } });
    // spins
    spinNow = h('div.adm-big');
    const spinIn = numIn('Количество', { min:0 });
    const setSpins = ()=>{
      const v = Number(spinIn.value);
      if(spinIn.value === '' || !Number.isFinite(v) || v < 0){ toast('Введи корректное число', 'err'); return; }
      totalSpins = Math.max(0, Math.floor(v));
      // unlocks auto-spin at 200 (doesn't switch it on)
      if(!autoSpinUnlocked && totalSpins >= 200) autoSpinUnlocked = true;
      updateSpinCounters(); updateTopStats(); updateAutoSpinButton(); refreshPlayer();
      toast(`Прокруток установлено: ${fmt(totalSpins)}`); spinIn.value = '';
    };
    spinIn.addEventListener('keydown', e=>{ if(e.key === 'Enter') setSpins(); });
    const spinCard = card('Прокрутки', 'От 200 прокруток открывается авто-прокрутка.', spinNow, h('div.adm-row', null, spinIn, btn('Установить', setSpins, 'primary')));
    // overrides
    luckIn = numIn('например 5000', { min:0 });
    speedIn = numIn('например 0.1', { min:0, step:'0.01' });
    ovrInfo = h('p.adm-note');
    const applyOvr = ()=>{
      const lv = Number(luckIn.value), sv = Number(speedIn.value);
      window._devLuckOverride = luckIn.value !== '' && Number.isFinite(lv) && lv > 0 ? lv : null;
      window._devSpinSeconds = speedIn.value !== '' && Number.isFinite(sv) && sv > 0 ? sv : null;
      updateTopStats(); updateAutoSpinButton(); refreshPlayer(); toast('Переопределения применены');
    };
    [luckIn, speedIn].forEach(i => i.addEventListener('keydown', e=>{ if(e.key === 'Enter') applyOvr(); }));
    const ovrCard = card('Удача и скорость', 'Заменяют итоговые значения целиком, пока не сбросишь. Пустое поле значит без переопределения.',
      h('div.adm-fields', null,
        h('label.adm-field', null, h('span', { text:'Удача, %' }), luckIn),
        h('label.adm-field', null, h('span', { text:'Задержка прокрутки, сек' }), speedIn)),
      h('div.adm-row', null, btn('Применить', applyOvr, 'primary'), btn('Сбросить', ()=>{
        window._devLuckOverride = null; window._devSpinSeconds = null; luckIn.value = ''; speedIn.value = '';
        updateTopStats(); updateAutoSpinButton(); refreshPlayer(); toast('Переопределения сброшены');
      }, 'danger')),
      ovrInfo);
    // quests
    questList = h('div.adm-quests');
    const questCard = card('Квесты', 'Мгновенно выполняет текущий квест линии: награда выдаётся, линия переходит к следующему.',
      questList,
      h('div.adm-row', null, btn('Выполнить текущие во всех линиях', ()=> completeQuests(null), 'primary')));
    // backup: copy the current slot out as text, or paste one back in
    const saveBox = h('textarea.adm-in.adm-save', { rows:3, placeholder:'Сюда вставляется или копируется сохранение', spellcheck:'false' });
    const saveCard = card('Сохранение', 'Резервная копия текущего слота. Вставка заменит слот и перезагрузит игру.',
      saveBox,
      h('div.adm-row', null,
        btn('Скопировать', ()=>{
          try{ saveStateToSlot(currentSaveSlot); saveBox.value = localStorage.getItem(getSaveKey(currentSaveSlot)) || ''; copyText(saveBox); }catch(e){ toast('Не удалось прочитать сохранение', 'err'); }
        }, 'primary'),
        btn('Вставить и перезагрузить', ()=>{
          const raw = (saveBox.value || '').trim();
          let ok = false; try{ const o = JSON.parse(raw); ok = o && typeof o === 'object' && ('coins' in o || 'inventory' in o); }catch(e){}
          if(!ok){ toast('Это не похоже на сохранение игры', 'err'); return; }
          try{ localStorage.setItem(getSaveKey(currentSaveSlot), raw); }catch(e){ toast('Не удалось записать', 'err'); return; }
          window._wipingProgress = true; // keep autosave from writing the old state back
          location.reload();
        }, 'danger')));
    sec.appendChild(h('div.adm-cards', null, coinCard, spinCard, ovrCard, questCard, saveCard));
    return sec;
  }
  function completeQuests(onlyLine){
    if(typeof QUEST_LINES === 'undefined'){ toast('Система квестов ещё не готова', 'err'); return; }
    let any = false;
    Object.keys(QUEST_LINES).forEach(lineId=>{
      if(onlyLine && lineId !== onlyLine) return;
      const line = QUEST_LINES[lineId];
      const s = getQuestState(lineId);
      const quest = line.quests[s.questIndex];
      if(!quest) return;
      if(!s.progress[s.questIndex]) s.progress[s.questIndex] = {};
      quest.tasks.forEach((task, ti)=>{ s.progress[s.questIndex][ti] = task.target; });
      completeQuest(lineId);
      any = true;
    });
    toast(any ? 'Квест выполнен, награда выдана' : 'Нет активных квестов', any ? '' : 'err');
    refreshPlayer();
  }
  function refreshPlayer(){
    if(!coinNow) return;
    coinNow.innerHTML = `${fmt(coins)} <span>🪙</span>`;
    spinNow.textContent = fmt(totalSpins);
    const l = window._devLuckOverride, s = window._devSpinSeconds;
    ovrInfo.textContent = (l === null || l === undefined) && (s === null || s === undefined)
      ? 'Сейчас переопределений нет.'
      : `Сейчас: удача ${l ? fmt(l) + '%' : 'без изменений'}, задержка ${s ? s + ' с' : 'без изменений'}.`;
    questList.innerHTML = '';
    if(typeof QUEST_LINES === 'undefined') return;
    Object.keys(QUEST_LINES).forEach(lineId=>{
      const line = QUEST_LINES[lineId];
      const s2 = getQuestState(lineId);
      const quest = line.quests[s2.questIndex];
      questList.appendChild(h('div.adm-quest', null,
        h('div', null, h('b', { text:line.name || lineId }), h('small', { text: quest ? `${quest.title || 'Квест ' + (s2.questIndex + 1)} из ${line.quests.length}` : 'Все квесты пройдены' })),
        quest ? btn('Выполнить', ()=> completeQuests(lineId), 'soft') : h('span.adm-done', { text:'✓' })));
    });
  }

  // ---------- Мир ----------
  let timeBtns = {}, weatherGrid, wDurIn, worldNote;
  function buildWorld(){
    const sec = h('div.adm-sec', { 'data-sec':'world', hidden:true });
    sec.appendChild(h('div.adm-sec-h', null, h('h2', { text:'Мир' }), h('p', { text:'Погода и время включаются сразу, таймер следующей смены перезапускается.' })));
    const timeRow = h('div.adm-time');
    [['День','☀️'],['Ночь','🌙']].forEach(([t, ic])=>{
      timeBtns[t] = h('button.adm-time-b', { type:'button', onclick:()=>{ setTimeNow(t); refreshWorld(); toast('Время: ' + t); } }, h('span', { text:ic }), t);
      timeRow.appendChild(timeBtns[t]);
    });
    const timeCard = card('Время суток', null, timeRow);
    wDurIn = numIn('мин', { min:1, class:'adm-in adm-in-s' });
    weatherGrid = h('div.adm-weather');
    WEATHERS.forEach(w=>{
      weatherGrid.appendChild(h('button.adm-w', { type:'button', 'data-w':w.name, style:{ '--w':w.color }, onclick:()=>{
        const mins = Math.floor(Number(wDurIn.value));
        setWeatherNow(w.name, mins > 0 ? mins * 60000 : undefined);
        refreshWorld(); toast('Погода: ' + w.name + (mins > 0 ? `, ${mins} мин` : ''));
      } }, h('b', { text:w.name }), h('small', { text:`шанс ${w.chance}, ${Math.round(w.dur() / 60000)} мин` })));
    });
    worldNote = h('p.adm-note');
    const weatherCard = card('Погода', 'Шанс указан для каждой смены погоды.', weatherGrid,
      h('div.adm-row', null,
        h('label.adm-field.adm-field-inline', null, h('span', { text:'Своя длительность' }), wDurIn),
        btn('Случайная по шансам', ()=>{ const w = rollNextWeather(); const mins = Math.floor(Number(wDurIn.value)); setWeatherNow(w, mins > 0 ? mins * 60000 : undefined); refreshWorld(); toast('Выпала погода: ' + w); }, 'soft')),
      worldNote);
    sec.appendChild(h('div.adm-cards', null, timeCard, weatherCard));
    return sec;
  }
  function refreshWorld(){
    if(!weatherGrid) return;
    Object.keys(timeBtns).forEach(t => timeBtns[t].classList.toggle('on', gameTime === t));
    weatherGrid.querySelectorAll('[data-w]').forEach(b => b.classList.toggle('on', b.dataset.w === currentWeather));
    const wEnds = window._weatherEndsAt ? window._weatherEndsAt - Date.now() : weatherRemainingMs;
    worldNote.textContent = `Сейчас «${currentWeather}», смена через ${mmss(wEnds)}. Время: ${gameTime}, смена через ${mmss(timeRemainingMs)}.`;
  }

  // ---------- Коды ----------
  // shared reward builder: searchable list of coins / auras / potions / gear + qty
  function rewardBuilder(list, emptyText){
    const opts = [{ v:'coins::__coins__', t:'🪙 Монеты', g:'Монеты' }];
    const byName = (a, b)=> (a.t || '').localeCompare(b.t || '', 'ru');
    const auras = [], gear = [], pots = [];
    Object.keys(ITEMS).forEach(k=>{
      const m = ITEMS[k]; if(!m) return;
      if(m.rarity && m.rarity !== '-') auras.push({ v:'aura::' + k, t:m.name || k, g:'Ауры' });
      else if(m.rarity === '-' && !m.isKey) gear.push({ v:'aura::' + k, t:m.name || k, g:'Снаряжение' }); // equipment grants like an aura
    });
    Object.keys(POTIONS).forEach(k => pots.push({ v:'potion::' + k, t:POTIONS[k].name || k, g:'Зелья' }));
    const all = opts.concat(auras.sort(byName), pots.sort(byName), gear.sort(byName));
    const search = h('input.adm-in', { type:'search', placeholder:'Найти награду', 'aria-label':'Найти награду' });
    const sel = h('select.adm-in.adm-list', { size:6, 'aria-label':'Награда' });
    function fill(){
      const q = search.value.trim().toLowerCase();
      sel.innerHTML = '';
      let grp = null, cur = '';
      all.filter(o => !q || o.t.toLowerCase().includes(q) || o.v.toLowerCase().includes(q)).forEach(o=>{
        if(o.g !== cur){ cur = o.g; grp = h('optgroup', { label:o.g }); sel.appendChild(grp); }
        grp.appendChild(h('option', { value:o.v, text:o.t }));
      });
      if(sel.options.length) sel.selectedIndex = 0;
    }
    fill();
    search.addEventListener('input', fill);
    const qty = numIn('кол-во', { min:1, value:1, class:'adm-in adm-in-s' });
    const chips = h('div.adm-tags');
    function label(e){
      if(e.rt === 'coins') return `🪙 Монеты ×${fmt(e.rq)}`;
      const meta = e.rt === 'aura' ? ITEMS[e.ri] : POTIONS[e.ri];
      return `${(meta && meta.name) || e.ri} ×${fmt(e.rq)}`;
    }
    function render(){
      chips.innerHTML = '';
      if(!list.length){ chips.appendChild(h('span.adm-note', { text:emptyText })); return; }
      list.forEach((e, i)=> chips.appendChild(h('span.adm-tag', null, label(e), h('button', { type:'button', 'aria-label':'Убрать', onclick:()=>{ list.splice(i, 1); render(); } }, '✕'))));
    }
    function add(){
      if(!sel.value){ toast('Выбери награду из списка', 'err'); return; }
      const [rt, ri] = sel.value.split('::');
      const rq = Math.max(1, Math.floor(Number(qty.value) || 1));
      // the same reward twice just stacks its quantity
      const same = list.find(e => e.rt === rt && (rt === 'coins' || e.ri === ri));
      if(same) same.rq += rq; else list.push({ rt, ri: rt === 'coins' ? null : ri, rq });
      qty.value = '1'; render();
    }
    sel.addEventListener('dblclick', add);
    sel.addEventListener('keydown', e=>{ if(e.key === 'Enter'){ e.preventDefault(); add(); } });
    search.addEventListener('keydown', e=>{ if(e.key === 'Enter'){ e.preventDefault(); add(); } });
    render();
    return { el: h('div.adm-rb', null, search, sel, h('div.adm-row', null, qty, btn('Добавить награду', add, 'soft')), chips), render };
  }
  function outputRow(){
    const out = h('input.adm-in.adm-out', { type:'text', readonly:true, placeholder:'Код появится здесь', onclick:()=> out.select() });
    return { out, el: h('div.adm-row', null, out, btn('Копировать', ()=> copyText(out))) };
  }
  function buildCodes(){
    const sec = h('div.adm-sec', { 'data-sec':'codes', hidden:true });
    sec.appendChild(h('div.adm-sec-h', null, h('h2', { text:'Коды' }), h('p', { text:'Сгенерированный код вводится игроком в окне «Промокод». Двойной клик или Enter в списке добавляет награду.' })));
    // ---- Слова ----
    const wRewards = [];
    const wWord = h('input.adm-in', { type:'text', placeholder:'Слово на русском', autocomplete:'off' });
    const wTries = numIn('6', { min:1, value:6, class:'adm-in adm-in-s' });
    const wRB = rewardBuilder(wRewards, 'Добавь хотя бы одну награду');
    const wOut = outputRow();
    const wordCard = card('Слова', 'Игрок угадывает слово за заданное число попыток и получает награды.',
      h('div.adm-fields', null, h('label.adm-field', null, h('span', { text:'Слово' }), wWord), h('label.adm-field', null, h('span', { text:'Попыток' }), wTries)),
      h('div.adm-sub', { text:'Награды' }), wRB.el,
      h('div.adm-row', null, btn('Сгенерировать код', ()=>{
        const word = (wWord.value || '').trim().toUpperCase().replace(/[^А-ЯЁ]/g, '');
        if(!word){ toast('Введи слово русскими буквами', 'err'); wWord.focus(); return; }
        if(!wRewards.length){ toast('Добавь хотя бы одну награду', 'err'); return; }
        const attempts = Math.max(1, Math.floor(Number(wTries.value) || 6));
        const payload = { w:word, a:attempts, rewards:wRewards.map(r => ({ rt:r.rt, ri:r.ri, rq:r.rq })),
          id:'wc_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 8) };
        wOut.out.value = generateWordleCode(payload); wOut.out.select();
        toast('Код «Слова» готов, можно копировать');
      }, 'primary')), wOut.el);

    // ---- Промокод ----
    const pRewards = [];
    const pRB = rewardBuilder(pRewards, 'Наград нет (необязательно)');
    // weather (only one can apply)
    let pWeather = null;
    const pWSel = h('select.adm-in');
    WEATHERS.forEach(w => pWSel.appendChild(h('option', { value:w.name, text:w.name })));
    const pWDur = numIn('мин', { min:1, class:'adm-in adm-in-s' });
    const pWCur = h('div.adm-tags');
    function renderPW(){
      pWCur.innerHTML = '';
      if(!pWeather){ pWCur.appendChild(h('span.adm-note', { text:'Погода не меняется' })); return; }
      pWCur.appendChild(h('span.adm-tag', null, `☁️ ${pWeather.name}${pWeather.durationMin ? ', ' + pWeather.durationMin + ' мин' : ', обычная длительность'}`,
        h('button', { type:'button', 'aria-label':'Убрать', onclick:()=>{ pWeather = null; renderPW(); } }, '✕')));
    }
    renderPW();
    // buffs
    const pBuffs = [];
    const pBuffTags = h('div.adm-tags');
    function buffLabel(b){
      if(b.existingId){ const m = POTIONS[b.existingId]; return `🧪 ${(m && m.name) || b.existingId}`; }
      const c = b.custom, bits = [];
      if(c.fixedLuck) bits.push(`удача = ${c.fixedLuck}%`);
      if(c.fixedSpeed) bits.push(`скорость = ${c.fixedSpeed}/с`);
      if(c.luckPercent) bits.push(`+${c.luckPercent}% удачи`);
      if(c.speedPercent) bits.push(`+${c.speedPercent}% скорости`);
      if(c.luckMultiplier) bits.push(`×${c.luckMultiplier} удача`);
      if(c.speedMultiplier) bits.push(`×${c.speedMultiplier} скорость`);
      if(c.bonusSpinModifier) bits.push(`бонус-прокрутка ×${c.bonusSpinModifier}`);
      const dur = c.spinCount ? `${c.spinCount} прокруток` : `${Math.round((c.durationMs || 60000) / 60000)} мин`;
      return `✨ ${c.name}: ${bits.join(', ') || 'без эффектов'} (${dur})`;
    }
    function renderBuffs(){
      pBuffTags.innerHTML = '';
      if(!pBuffs.length){ pBuffTags.appendChild(h('span.adm-note', { text:'Баффов нет' })); return; }
      pBuffs.forEach((b, i)=> pBuffTags.appendChild(h('span.adm-tag', null, buffLabel(b), h('button', { type:'button', 'aria-label':'Убрать', onclick:()=>{ pBuffs.splice(i, 1); renderBuffs(); } }, '✕'))));
    }
    renderBuffs();
    const modeSeg = h('div.adm-seg');
    const exSel = h('select.adm-in');
    Object.keys(POTIONS).sort((a, b)=> (POTIONS[a].name || a).localeCompare(POTIONS[b].name || b, 'ru')).forEach(k => exSel.appendChild(h('option', { value:k, text:POTIONS[k].name || k })));
    const exWrap = h('div.adm-row', null, exSel);
    const f = {};
    const fld = (key, label, ph, step)=>{ f[key] = numIn(ph, step ? { step } : null); return h('label.adm-field', null, h('span', { text:label }), f[key]); };
    const cName = h('input.adm-in', { type:'text', placeholder:'Кастомный бафф' });
    const cDesc = h('textarea.adm-in', { rows:2, placeholder:'Показывается в инвентаре и в подсказке баффа' });
    const cColor = h('input.adm-color', { type:'color', value:'#ffb84d' });
    const durMode = h('select.adm-in', null, h('option', { value:'time', text:'минут' }), h('option', { value:'spins', text:'прокруток' }));
    const durVal = numIn('1', { min:1 });
    const customWrap = h('div.adm-custom', { hidden:true },
      h('div.adm-fields', null,
        h('label.adm-field', null, h('span', { text:'Название' }), cName),
        h('label.adm-field.adm-field-color', null, h('span', { text:'Цвет' }), cColor)),
      h('label.adm-field', null, h('span', { text:'Описание (необязательно)' }), cDesc),
      h('div.adm-fields.adm-fields-3', null,
        fld('lp', '+% удачи', '50'), fld('sp', '+% скорости', '20'), fld('bs', 'Бонус-прокрутка ×', '5'),
        fld('lm', 'Множитель удачи', '2', 'any'), fld('sm', 'Множитель скорости', '1.5', 'any'), fld('fl', 'Фикс. удача, %', '5000'),
        fld('fs', 'Фикс. скорость, прокр/с', '8', 'any')),
      h('div.adm-row', null, h('span.adm-note', { text:'Длится' }), durVal, durMode));
    let mode = 'existing';
    [['existing','Бафф из игры'],['custom','Свой бафф']].forEach(([m, l])=>{
      modeSeg.appendChild(h('button.adm-seg-b' + (m === mode ? '.on' : ''), { type:'button', 'data-m':m, onclick:()=>{
        mode = m;
        modeSeg.querySelectorAll('[data-m]').forEach(b => b.classList.toggle('on', b.dataset.m === m));
        exWrap.hidden = m !== 'existing'; customWrap.hidden = m !== 'custom';
      } }, l));
    });
    function addBuff(){
      if(mode === 'existing'){ pBuffs.push({ existingId: exSel.value }); renderBuffs(); return; }
      const custom = { name:(cName.value || '').trim() || 'Кастомный бафф', color:cColor.value || '#ffb84d' };
      const desc = (cDesc.value || '').trim(); if(desc) custom.desc = desc;
      const map = { lp:'luckPercent', sp:'speedPercent', lm:'luckMultiplier', sm:'speedMultiplier', fl:'fixedLuck', fs:'fixedSpeed', bs:'bonusSpinModifier' };
      Object.keys(map).forEach(k=>{ const v = Number(f[k].value); if(v) custom[map[k]] = v; });
      const dv = Math.max(1, Math.floor(Number(durVal.value) || 1));
      if(durMode.value === 'spins') custom.spinCount = dv; else custom.durationMs = dv * 60000;
      pBuffs.push({ custom });
      cName.value = ''; cDesc.value = ''; durVal.value = ''; Object.values(f).forEach(i => { i.value = ''; });
      renderBuffs();
    }
    const pOut = outputRow();
    const promoCard = card('Промокод', 'Любая комбинация наград, смены погоды и баффов. Нужно хотя бы что-то одно.',
      h('div.adm-sub', { text:'Награды' }), pRB.el,
      h('div.adm-sub', { text:'Погода' }),
      h('div.adm-row', null, pWSel, pWDur, btn('Задать погоду', ()=>{
        const d = Math.max(0, Math.floor(Number(pWDur.value) || 0));
        pWeather = { name: pWSel.value }; if(d > 0) pWeather.durationMin = d; renderPW();
      }, 'soft')), pWCur,
      h('div.adm-sub', { text:'Баффы' }), modeSeg, exWrap, customWrap,
      h('div.adm-row', null, btn('Добавить бафф', addBuff, 'soft')), pBuffTags,
      h('div.adm-row', null, btn('Сгенерировать промокод', ()=>{
        if(!pRewards.length && !pWeather && !pBuffs.length){ toast('Добавь награду, погоду или бафф', 'err'); return; }
        const payload = { id:'pc_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 8), rewards:pRewards.map(r => ({ rt:r.rt, ri:r.ri, rq:r.rq })) };
        if(pWeather){ payload.weather = { name:pWeather.name }; if(pWeather.durationMin) payload.weather.durationMin = pWeather.durationMin; }
        if(pBuffs.length) payload.buffs = pBuffs.map(b => b.existingId ? { existingId:b.existingId } : { custom:{ ...b.custom } });
        pOut.out.value = generatePromoCode(payload); pOut.out.select();
        toast('Промокод готов, можно копировать');
      }, 'primary')), pOut.el);
    sec.appendChild(h('div.adm-cards.adm-cards-2', null, wordCard, promoCard));
    return sec;
  }

  // ---------- Музыка ----------
  let musicList, musicNow, musicSearch;
  const MUSIC_CLASS_ORDER = ['weak', 'decent', 'normal', 'good', 'very_good', 'super', 'incredible', 'special'];
  function buildMusic(){
    const sec = h('div.adm-sec', { 'data-sec':'music', hidden:true });
    sec.appendChild(h('div.adm-sec-h', null, h('h2', { text:'Музыка' }), h('p', { text:'У каждой ауры от «Нормального» и выше свой трек (и у пары туалетных). Если у темы трека нет, играет трек погоды, а при обычной погоде по кругу идут базовые. Прослушивание не меняет тему; после стопа вернётся то, что играло.' })));
    musicNow = h('div.adm-np');
    const vol = h('input.adm-range', { type:'range', min:0, max:100, value:Math.round(AMB.musicVolume * 100), 'aria-label':'Громкость музыки',
      oninput:()=>{ AMB.setMusicVolume(Number(vol.value) / 100); const r = document.getElementById('music-volume'); if(r){ r.value = vol.value; const l = document.getElementById('music-volume-val'); if(l) l.textContent = vol.value + '%'; } } });
    musicSearch = h('input.adm-in.adm-search', { type:'search', placeholder:'Найти трек, жанр или ауру', oninput:()=> refreshMusic() });
    musicList = h('div.adm-tracks');
    musicList.addEventListener('click', e=>{
      const rb = e.target.closest('[data-rain]');
      if(rb){
        if(window._rainPreview){ window._rainPreview = false; if(currentWeather !== 'Дождь') stopRainAudio(); }
        else { window._rainPreview = true; startRainAudio(); if(weatherVolume() <= 0.001) toast('Громкость звуков погоды на нуле', 'err'); }
        refreshMusic(); return;
      }
      const db = e.target.closest('[data-dl], [data-dlfile]');
      if(db){
        if(db.dataset.dlfile){
          fetch(encodeURI(db.dataset.dlfile)).then(r=> r.blob()).then(b=> saveBlob(b, trackFileName(db.dataset.dlname, db.dataset.dlfile.slice(db.dataset.dlfile.lastIndexOf('.'))))).catch(()=> toast('Файл не найден', 'err'));
          return;
        }
        if(_mp3Busy){ toast('Уже готовлю другой трек, подожди', 'err'); return; }
        const id = db.dataset.dl, T = PATCHES[id], label = db.textContent;
        db.disabled = true; db.classList.add('busy');
        if(!T.file) toast('Готовлю MP3: «' + T.name + '». Это займёт до минуты');
        downloadTrackMp3(id, (txt)=>{ db.textContent = txt; })
          .then(()=> toast('Скачано: ' + trackFileName(T.name, T.file ? T.file.slice(T.file.lastIndexOf('.')) : '.mp3')))
          .catch(()=> toast('Не получилось сделать MP3', 'err'))
          .finally(()=>{ db.disabled = false; db.classList.remove('busy'); db.textContent = label; });
        return;
      }
      const wb = e.target.closest('[data-wind]');
      if(wb){ AMB.windPreviewToggle(); if(weatherVolume() <= 0.001) toast('Громкость звуков погоды на нуле', 'err'); refreshMusic(); return; }
      const fb = e.target.closest('[data-sfx]');
      if(fb){
        try{ AMB.playFile(fb.dataset.sfx, 1.0); }catch(err){}
        if(AMB.sfxVolume <= 0.001) toast('Громкость звуков на нуле', 'err');
        fb.classList.add('adm-tr-hit'); setTimeout(()=> fb.classList.remove('adm-tr-hit'), 400);
        return;
      }
      const b = e.target.closest('[data-play]');
      if(!b) return;
      const id = b.dataset.play;
      if(AMB.previewing === id){ AMB.stopPreview(); }
      else { AMB.preview(id); if(AMB.musicVolume <= 0.001) toast('Громкость музыки на нуле', 'err'); }
      setTimeout(refreshMusic, 60);
    });
    // seek bar: file tracks scrub through the recording, generated tracks jump through their
    // arrangement (intro and the four sections that loop)
    const fmt = (x)=>{ x = Math.max(0, Math.floor(x)); return Math.floor(x / 60) + ':' + String(x % 60).padStart(2, '0'); };
    const seekCur = h('span.adm-seek-t', { text:'0:00' }), seekDur = h('span.adm-seek-t', { text:'0:00' });
    let seeking = false;
    const seek = h('input.adm-range.adm-seek', { type:'range', min:0, max:1000, value:0, 'aria-label':'Перемотка трека',
      oninput:()=>{ seeking = true; const p = AMB.position(); if(p) seekCur.textContent = fmt(Number(seek.value) / 1000 * p.dur); },
      onchange:()=>{ const p = AMB.position(); if(p) AMB.seek(Number(seek.value) / 1000 * p.dur); seeking = false; } });
    const jump = (d)=>{ const p = AMB.position(); if(p) AMB.seek(Math.max(0, Math.min(p.dur - 0.5, p.pos + d))); };
    const seekRow = h('div.adm-row.adm-seek-row', null, btn('−10 с', ()=> jump(-10), 'soft'), seekCur, seek, seekDur, btn('+10 с', ()=> jump(10), 'soft'));
    setInterval(()=>{
      if(!admIsOpen() || st.sec !== 'music') return;
      const p = AMB.position();
      seekRow.classList.toggle('adm-dim', !p);
      if(!p || seeking) return;
      seek.value = String(Math.round(p.pos / Math.max(0.001, p.dur) * 1000));
      seekCur.textContent = fmt(p.pos); seekDur.textContent = fmt(p.dur);
    }, 250);
    sec.appendChild(h('div.adm-card.adm-np-card', null, musicNow, seekRow,
      h('div.adm-row', null, h('span.adm-note', { text:'Громкость' }), vol,
        btn('Стоп', ()=>{ AMB.stopPreview(); setTimeout(refreshMusic, 60); }, 'soft'))));
    sec.appendChild(h('div.adm-toolbar', { style:{ marginTop:'14px' } }, musicSearch));
    sec.appendChild(musicList);
    window.addEventListener('amb-track', ()=>{ if(admIsOpen() && st.sec === 'music') refreshMusic(); });
    return sec;
  }
  function refreshMusic(){
    if(!musicList) return;
    const cur = AMB.current, prev = AMB.previewing;
    const P = cur && PATCHES[cur];
    musicNow.innerHTML = P
      ? `<span class="adm-np-ic"><svg viewBox="0 0 24 24" width="22" height="22" fill="currentColor" aria-hidden="true"><path d="M9 17.5a3 3 0 1 1-2-2.83V5.5l11-2v11.5a3 3 0 1 1-2-2.83V7.3l-7 1.27z"/></svg></span><div><small>${prev ? 'Прослушивание' : 'Играет в теме'}</small><b>${esc(P.name)}</b><span>${esc(P.genre)}, ${esc(P.weather ? 'погода «' + P.weather + '»' : P.base ? 'базовый трек' : ((ITEMS[cur] || {}).name || cur))}</span></div>`
      : `<span class="adm-np-ic"><svg viewBox="0 0 24 24" width="22" height="22" fill="currentColor" aria-hidden="true"><path d="M9 17.5a3 3 0 1 1-2-2.83V5.5l11-2v11.5a3 3 0 1 1-2-2.83V7.3l-7 1.27z"/></svg></span><div><small>Сейчас</small><b>Тишина</b><span>Выбери трек ниже или включи тему с музыкой</span></div>`;
    const q = (musicSearch.value || '').trim().toLowerCase();
    const groups = {};
    Object.keys(PATCHES).forEach(id=>{
      const T = PATCHES[id], aura = T.weather ? 'погода ' + T.weather : T.base ? 'базовый' : ((ITEMS[id] || {}).name || id);
      if(q && !(T.name + ' ' + T.genre + ' ' + aura + ' ' + id).toLowerCase().includes(q)) return;
      const cls = T.base ? '_base' : T.weather ? '_wx' : (rarityClassKeyFor(id) || 'special');
      (groups[cls] || (groups[cls] = [])).push(id);
    });
    musicList.innerHTML = '';
    const GROUP_META = { _base:{ name:'Базовые (играют, когда у темы нет своего трека)', color:'#7a8a80' }, _wx:{ name:'Погода', color:'#2f6fd0' } };
    ['_base', '_wx'].concat(MUSIC_CLASS_ORDER).forEach(cls=>{
      const ids = groups[cls]; if(!ids) return;
      if(!GROUP_META[cls]) ids.sort((a, b)=> (getNativeDenominatorForItem(ITEMS[a] || {}) || 0) - (getNativeDenominatorForItem(ITEMS[b] || {}) || 0));
      const meta = GROUP_META[cls] || RARITY_CLASS_META[cls];
      musicList.appendChild(h('div.adm-tr-h', { style:{ '--rc':meta.color } }, GROUP_META[cls] ? meta.name : cls === 'incredible' ? 'Невероятный' : meta.name.charAt(0) + meta.name.slice(1).toLowerCase()));
      ids.forEach(id=>{
        const T = PATCHES[id], on = cur === id;
        const row = h('div.adm-tr' + (on ? '.on' : ''), { style:{ '--rc':meta.color } });
        row.innerHTML = `<button type="button" class="adm-tr-dl" data-dl="${esc(id)}" aria-label="Скачать ${esc(T.name)} в MP3" title="Скачать MP3">⬇ MP3</button><button type="button" class="adm-tr-play" data-play="${esc(id)}" aria-label="${on && prev === id ? 'Остановить' : 'Слушать'} ${esc(T.name)}">${on && prev === id ? '■' : '▶'}</button>`
          + `<div class="adm-tr-main"><b>${esc(T.name)}</b><span>${esc(T.genre)}</span></div>`
          + `<div class="adm-tr-aura">${T.weather ? 'Погода «' + esc(T.weather) + '»' : T.base ? 'Без своего трека' : styledRarityName(id, (ITEMS[id] || {}).name || id, true)}</div>`
          + (T.file ? `<code>свой файл</code>` : `<code>${esc(T.key)} ${esc(T.scale)}, ${AMB.bpmOf(id) || ''} bpm</code>`);
        musicList.appendChild(row);
      });
    });
    // weather ambience: the player's own rain recording
    if(!q || 'дождь погода rain ветер wind'.includes(q)){
      const on = !!window._rainPreview;
      musicList.appendChild(h('div.adm-tr-h', { style:{ '--rc':'#2f6fd0' } }, 'Звуки погоды'));
      const row = h('div.adm-tr' + (on ? '.on' : ''), { style:{ '--rc':'#2f6fd0' } });
      row.innerHTML = `<button type="button" class="adm-tr-dl" data-dlfile="30 MINUTES Rain Sounds (no music or thunder), Light Rain for Sleep, Relaxing, Meditate, Study, Yoga 4.mp3" data-dlname="Дождь" title="Скачать файл">⬇ MP3</button><button type="button" class="adm-tr-play" data-rain="1" aria-label="${on ? 'Остановить' : 'Слушать'} дождь">${on ? '■' : '▶'}</button><div class="adm-tr-main"><b>Дождь</b><span>звук погоды, свой файл</span></div><div class="adm-tr-aura">Погода «Дождь»</div><code>громкость: Звуки погоды</code>`;
      musicList.appendChild(row);
      const won = !!AMB.windPreviewing;
      const wrow = h('div.adm-tr' + (won ? '.on' : ''), { style:{ '--rc':'#2f9f8a' } });
      wrow.innerHTML = `<button type="button" class="adm-tr-play" data-wind="1" aria-label="${won ? 'Остановить' : 'Слушать'} ветер">${won ? '■' : '▶'}</button><div class="adm-tr-main"><b>Ветер</b><span>звук погоды, синтез</span></div><div class="adm-tr-aura">Погода «Ветреная»</div><code>громкость: Звуки погоды</code>`;
      musicList.appendChild(wrow);
    }
    // the player's own sound files: every one of them is listed and follows a settings slider
    const SFX_OWN = [
      ['0611.mp3', 'Щелчок прокрутки', 'каждая прокрутка'],
      ['0611_1_.mp3', 'Выпадение «Слабый»', 'звук выпадения'],
      ['0611_2_ (1).mp3', 'Выпадение «Неплохой»', 'звук выпадения'],
      ['Big cinematic impact Sound Effect 4.mp3', 'Удар «Нормальный»', 'анимация выпадения'],
      ['mega-drop-impact.wav', 'Удар «Хороший»', 'анимация выпадения'],
      ['very-good-impact.mp3', 'Удар «Очень хороший» и выше', 'анимация выпадения'],
      ['Roblox Angry Sound Effect 4.mp3', 'Злой рык', 'тема «Злой»']
    ].filter(r=> !q || (r[1] + ' ' + r[2] + ' звук').toLowerCase().includes(q));
    if(SFX_OWN.length){
      musicList.appendChild(h('div.adm-tr-h', { style:{ '--rc':'#c98a1a' } }, 'Твои звуки'));
      SFX_OWN.forEach(([file, name, use])=>{
        const row = h('div.adm-tr', { style:{ '--rc':'#c98a1a' } });
        row.innerHTML = `<button type="button" class="adm-tr-dl" data-dlfile="${esc(file)}" data-dlname="${esc(name)}" title="Скачать файл">⬇ ${esc(file.slice(file.lastIndexOf('.') + 1).toUpperCase())}</button><button type="button" class="adm-tr-play" data-sfx="${esc(file)}" aria-label="Проиграть ${esc(name)}">▶</button><div class="adm-tr-main"><b>${esc(name)}</b><span>${esc(use)}, свой файл</span></div><div class="adm-tr-aura">${esc(file.slice(1))}</div><code>громкость: Звуки выпадения</code>`;
        musicList.appendChild(row);
      });
    }
    if(!musicList.childElementCount) musicList.appendChild(h('div.adm-empty', { text:'Ничего не найдено' }));
  }

  // ---------- Проверка: темы и анимации ----------
  let testGrid, testSearch;
  function buildTests(){
    const sec = h('div.adm-sec', { 'data-sec':'tests', hidden:true });
    sec.appendChild(h('div.adm-sec-h', null, h('h2', { text:'Проверка' }), h('p', { text:'Включи любую тему без выдачи ауры или посмотри анимацию её выпадения. Панель закроется, чтобы было видно.' })));
    testSearch = h('input.adm-in.adm-search', { type:'search', placeholder:'Найти ауру', oninput:()=> renderTests() });
    testGrid = h('div.adm-tests');
    testGrid.addEventListener('click', e=>{
      const b = e.target.closest('[data-act]'); if(!b) return;
      const id = b.dataset.id;
      if(b.dataset.act === 'theme'){
        activeThemeId = id; applyThemeForItem(id);
        close();
      } else if(b.dataset.act === 'fx'){
        const cls = rarityClassKeyFor(id);
        const tier = cls === 'normal' ? 'normal' : (cls === 'good' || cls === 'special') ? 'good' : 'very_good';
        close();
        setTimeout(()=>{ try{ DropFX.play(id, ITEMS[id].name || id, tier, null, { denom:getNativeDenominatorForItem(ITEMS[id]), cls }); }catch(err){} }, 200);
      }
    });
    sec.appendChild(h('div.adm-toolbar', null, testSearch,
      btn('Снять тему', ()=>{
        activeThemeId = null; applyThemeForItem(null);
        const ar = document.getElementById('active-rarity'); if(ar){ ar.classList.remove('show'); ar.setAttribute('aria-hidden', 'true'); }
        try{ applyWeatherTheme(true); }catch(e){}
        toast('Тема снята');
      }, 'soft')));
    sec.appendChild(testGrid);
    return sec;
  }
  function renderTests(){
    if(!testGrid) return;
    const q = (testSearch.value || '').trim().toLowerCase();
    const ids = listFor('auras').filter(id=> !q || (ITEMS[id].name || '').toLowerCase().includes(q) || id.includes(q));
    testGrid.innerHTML = '';
    const frag = document.createDocumentFragment();
    ids.forEach(id=>{
      const cls = rarityClassKeyFor(id);
      const hasFx = cls && cls !== 'common' && cls !== 'weak' && cls !== 'decent';
      const row = h('div.adm-test', { style:{ '--rc':(RARITY_CLASS_META[cls] || {}).color || '#999' } });
      row.innerHTML = `<div class="adm-test-name">${readableName(styledRarityName(id, ITEMS[id].name, true))}<small>${esc(ITEMS[id].rarity || '')}${PATCHES[id] ? ', ♪ ' + esc(PATCHES[id].name) : ''}</small></div>`
        + `<button type="button" class="adm-mini" data-act="theme" data-id="${esc(id)}">Тема</button>`
        + (hasFx ? `<button type="button" class="adm-mini" data-act="fx" data-id="${esc(id)}">Выпадение</button>` : '');
      frag.appendChild(row);
    });
    testGrid.appendChild(frag);
  }

  // ---------- open / close / unlock ----------
  function onKey(e){
    if(!admIsOpen()) return;
    const typing = e.target && (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA' || e.target.tagName === 'SELECT' || e.target.isContentEditable);
    if(e.key === 'Escape'){
      e.preventDefault(); e.stopImmediatePropagation();
      if(typing && e.target.value && e.target.type === 'search'){ e.target.value = ''; e.target.dispatchEvent(new Event('input')); return; }
      close(); return;
    }
    if(!devUnlocked || typing) return;
    if(/^[1-6]$/.test(e.key)){ e.preventDefault(); show(['give','player','world','codes','music','tests'][Number(e.key) - 1]); return; }
    if(e.key === '/'){ e.preventDefault(); show('give'); searchIn.focus(); searchIn.select(); }
  }
  function open(){
    if(!root) buildShell();
    devPanel.setAttribute('aria-hidden', 'false');
    document.body.classList.add('adm-open');
    if(devUnlocked){ enter(); return; }
    root.classList.remove('unlocked');
    codeErr.textContent = ''; codeInput.value = '';
    setTimeout(()=> codeInput.focus(), 30);
  }
  function enter(){
    buildConsole();
    root.classList.add('unlocked');
    show(st.sec);
    refreshStats();
    clearInterval(tickId);
    tickId = setInterval(()=>{ refreshStats(); if(st.sec === 'world') refreshWorld(); }, 1000);
  }
  function close(){
    devPanel.setAttribute('aria-hidden', 'true');
    document.body.classList.remove('adm-open');
    clearInterval(tickId); tickId = null;
    if(devBtn) devBtn.focus({ preventScroll:true });
  }
  function tryUnlock(){
    const val = (codeInput.value || '').trim();
    if(!val){ codeErr.textContent = 'Введи код'; return; }
    if(val.toUpperCase() === UNLOCK_CODE){ devUnlocked = true; codeErr.textContent = ''; enter(); }
    else { devUnlocked = false; codeErr.textContent = 'Неверный код'; codeInput.select(); }
  }
  document.addEventListener('keydown', onKey, true);
  // click on the empty backdrop of the lock screen closes it
  if(devPanel) devPanel.addEventListener('click', e=>{ if(e.target === lockEl && !devUnlocked) close(); });
  return { open, close, isOpen: admIsOpen, refresh: ()=>{ if(!admIsOpen() || !built) return; refreshStats(); if(st.sec === 'give') renderGrid(); if(st.sec === 'player') refreshPlayer(); } };
})();
function openDevPanel(){ ADM.open(); }
function closeDevPanel(){ ADM.close(); }
if(devBtn) devBtn.addEventListener('click', openDevPanel);

