// helper to sum available counts for an item id (fall back to 0)
// supports both inventory entries and POTIONS (potions stored separately)
function availableCountFor(id){
  // potions are in POTIONS object with .count
  if(id && POTIONS[id] && typeof POTIONS[id].count === 'number'){
    return Math.max(0, POTIONS[id].count);
  }
  // normal inventory items
  ensureItem(id);
  return inventory[id] ? inventory[id].count : 0;
}

