// splits text into one span per character with a staggered bounce delay (used for "wave" values)
function waveLetters(text){
  return String(text).split('').map((ch, i)=>{
    const safe = (ch === ' ') ? '&nbsp;' : ch;
    return `<span class="rn-wave-letter" style="animation-delay:${i*80}ms">${safe}</span>`;
  }).join('');
}

function styledRarityName(id, nameOverride, simple){
  const meta = ITEMS[id] || {};
  const name = (nameOverride !== undefined && nameOverride !== null) ? nameOverride : (meta.name || id || '');
  const tier = rarityNameTier(id);
  const override = RARITY_NAME_STYLE[id] || {};
  const color = override.color || rarityColorFor(id);
  const prefix = override.prefix || '';
  const suffix = override.suffix || '';
  const classes = ['rn', 'rn-t' + tier];
  // "simple" mode: used in list-heavy contexts (craft cards/ingredients, dev panel, filter
  // list) where potentially dozens of names render at once — skipping the animated/gradient
  // extraClass here (glow, shifting gradients, shake, etc.) avoids running many expensive
  // CSS animations simultaneously, which was a real source of CPU load. The wave-letter
  // splitting is skipped too for the same reason. Single prominent displays (inventory card,
  // decision modal, big-drop overlay, aura-title) still call this without `simple` and get
  // the full glam treatment.
  if(!simple && override.extraClass) classes.push(override.extraClass);
  const body = (!simple && override.wave) ? waveLetters(name) : (prefix + name + suffix);
  return `<span class="${classes.join(' ')}" style="color:${color}">${body}</span>`;
}

// ---- Rarity classes (outline color + class name shown on cards) ----
// A coarser grouping than individual values — every value belongs to exactly one class,
// based on its rarity denominator, with a short list of explicit exceptions/overrides.
const RARITY_CLASS_META = {
  common:     { name: 'Обычный',                color: '#111111' },
  weak:       { name: 'Слабый',                 color: '#c2557f' },
  decent:     { name: 'Неплохой',                color: '#d97b1f' },
  normal:     { name: 'Нормальный',              color: '#b8960f' },
  good:       { name: 'Хороший',                 color: '#7fae2e' },
  very_good:  { name: 'Очень Хороший',           color: '#2f8a3c' },
  super:      { name: 'СУПЕРСКИЙ',               color: '#1e6fe6' },
  incredible: { name: 'Н Е В Е Р О Я Т Н Ы Й',   color: '#1e6fe6' }, // shifting gradient via CSS
  special:    { name: 'Особенный',               color: '#8a5cc4' }
};
// event/limited auras always count as "Особенный", regardless of their numeric rarity
const RARITY_CLASS_SPECIAL_IDS = new Set(['cool_summer', 'glokys', 'turtle_sea', 'pumpkin']);
// explicit exceptions that don't follow the numeric ranges below
const RARITY_CLASS_EXCEPTIONS = { kal: 'weak', mag_mage: 'decent', big_pearl: 'very_good', dragon_fruit: 'special', matrix_binary: 'decent', matrix_code: 'normal', matrix_null: 'good',
  // promoted by request: Love and Сакура both sit in «Нормальный»
  love: 'normal', sakura: 'normal' };

function rarityClassKeyFor(id){
  if(RARITY_CLASS_SPECIAL_IDS.has(id)) return 'special';
  if(RARITY_CLASS_EXCEPTIONS[id]) return RARITY_CLASS_EXCEPTIONS[id];
  const meta = ITEMS[id];
  if(!meta || meta.rarity === '-') return null; // equipment: no rarity class
  const denom = getNativeDenominatorForItem(meta);
  if(!denom || denom <= 0) return 'special'; // any other craft-only/unobtainable value
  if(denom < 1000) return 'common';           // 1 - 999
  if(denom < 10000) return 'weak';            // 1 000 - 9 999
  if(denom < 100000) return 'decent';         // 10 000 - 99 999
  if(denom < 1000000) return 'normal';        // 100 000 - 999 999
  if(denom < 10000000) return 'good';         // 1 000 000 - 9 999 999
  if(denom < 100000000) return 'very_good';   // 10 000 000 - 99 999 999
  if(denom < 1000000000) return 'super';      // 100 000 000 - 999 999 999
  return 'incredible';                        // 1 000 000 000+
}
function rarityClassCssKeyFor(id){
  const key = rarityClassKeyFor(id);
  return key ? key.replace(/_/g, '-') : '';
}
// small badge showing the class name, styled consistently everywhere it appears
function rarityClassBadge(id){
  const key = rarityClassKeyFor(id);
  if(!key) return '';
  const meta = RARITY_CLASS_META[key];
  const cssKey = key.replace(/_/g, '-');
  return `<span class="rc-badge rc-label-${cssKey}">${meta.name}</span>`;
}

