  // inventory state: counts and values rolled
 // inventory holds counts per item id; inventory slot limit counts distinct item ids with count>0
 const inventory = {
   // id -> {count:number, times:number}
 };

 // record of values the user has ever obtained from a roll (seen by RNG at least once)
 // keys: item id -> true
 if(typeof window._seenItems === 'undefined') window._seenItems = {};

 // inventory slots and expansion pricing
 let inventoryMaxSlots = 10;
 let expansionPrice = 100; // базовое значение, но фактическая цена теперь вычисляется от количества расширений
 // фактическая логика цены описана в expandInventory / updateExpandButtonLabel
// whether skipper is activated (equipped) to skip previews
let skipperActive = false;

function ensureItem(id){
  if(!inventory[id]) inventory[id] = {count:0, times:0, pulls: []};
  if(!Array.isArray(inventory[id].pulls)) inventory[id].pulls = [];
}

// Records N new "pull instances" for a value (used so duplicates can be shown as separate
// cards in the inventory, each remembering which spin # and what time it was obtained).
function recordPulls(id, qty = 1){
  ensureItem(id);
  const arr = inventory[id].pulls;
  const spinNow = (typeof totalSpins === 'number') ? totalSpins : 0;
  const timeNow = Date.now();
  const luckNow = (typeof window._lastRollLuckPercent === 'number')
    ? window._lastRollLuckPercent
    : (typeof getCurrentLuckPercent === 'function' ? getCurrentLuckPercent() : null);
  for(let i=0;i<qty;i++){
    arr.push({
      uid: 'p' + timeNow.toString(36) + Math.random().toString(36).slice(2,8) + i,
      spin: spinNow,
      time: timeNow,
      luck: luckNow
    });
  }
  // the "last roll luck" only applies to the very next recordPulls call after an actual spin —
  // clear it so unrelated grants (dev/craft/promo) that happen afterwards don't inherit it
  window._lastRollLuckPercent = null;
}

// Keeps inventory[id].pulls in sync with inventory[id].count — pads with "unknown origin"
// placeholder entries for legacy saves that predate pull-tracking, and trims any excess.
function normalizeInventoryPulls(){
  Object.keys(inventory).forEach(id=>{
    ensureItem(id);
    const data = inventory[id];
    const count = Math.max(0, data.count || 0);
    while(data.pulls.length < count){
      data.pulls.push({ uid: 'legacy' + data.pulls.length + '_' + id, spin: null, time: null, luck: null });
    }
    if(data.pulls.length > count){
      data.pulls.length = count;
    }
  });
}

// Removes one specific pull instance (by uid) from a value's inventory — used by the
// "Карточка значения" panel's Delete button so removing one duplicate doesn't affect the others.
function removePullInstance(id, uid){
  // "Особенный"-class auras (event auras) live in the unlimited Особые tab and can never
  // be deleted — enforced here, at the single lowest-level entry point, so no UI path
  // (value card panel, multi-select, or anything added later) can bypass it.
  if(rarityClassKeyFor(id) === 'special') return false;
  ensureItem(id);
  const data = inventory[id];
  const idx = data.pulls.findIndex(p => p.uid === uid);
  if(idx === -1) return false;
  data.pulls.splice(idx, 1);
  data.count = Math.max(0, data.count - 1);
  return true;
}

