    const tg = c.createGain(); tg.gain.setValueAtTime(v * 0.08, t); tg.gain.setTargetAtTime(0.0001, t, 0.02);
    const a = c.createGain();
    a.gain.setValueAtTime(0.0001, t); a.gain.linearRampToValueAtTime(v, t + 0.004);
    a.gain.setTargetAtTime(v * 0.35, t + 0.004, 0.9);
