    H.each(ch.slice(1), (m, i)=> H.ep(2.5, m, 1.2, 0.04, { pan:0.15 }));
    H.d('kick', 0, 0.38, { f:52, dec:0.28, lp:260 }); H.d('kick', 2.25, 0.26, { f:52, dec:0.25, lp:260 });
    H.d('snare', 1, 0.11, { dec:0.12 }); H.d('snare', 3, 0.13, { dec:0.12 });
    for(let b = 0; b < 4; b += 0.5) H.d('hat', b, b % 1 ? 0.025 : 0.04, { dec:0.025 });
    H.v(V.upright, 0, H.rm(-2), 1.6, 0.1); H.v(V.upright, 2.5, H.rm(-2) + 7, 1.2, 0.08);
    if(H.lvl >= 1) H.mel((n)=> H.ks('nylon', n.at, n.m, n.len, 0.06, { pan:0.25 }), 0);
