const RG_SEL = ['#top-stats > div', '#top-stats > div span', '#coin-counter', '.wt-badge', '.wt-badge span', '.wt-sub', '.wt-sub span',
  '#inventory-btn', '#quests-btn', '#words-btn', '#spin-btn', '#auto-spin-btn', '#active-rarity', '#dev-btn', '#anvil-btn', '#brewery-btn',
  '#bank-btn', '#settings-btn', '#save-btn', '#clear-theme-btn', '#ui-toggle-btn', '#start-menu-btn', '.key-hint', '#spin-countdown', '#spin-countdown span',
  '#now-playing b', '#now-playing small', '#now-playing span'];
const RG_PROPS = ['color', 'opacity', 'background-color', 'padding', 'border-radius', 'width', 'margin-left', 'margin-right', 'backdrop-filter', '-webkit-backdrop-filter', 'text-shadow'];
