      rgSet(el, 'padding', '3px 12px');
      rgSet(el, 'border-radius', '999px');
      if(cs.display === 'block'){ rgSet(el, 'width', 'max-content'); rgSet(el, 'margin-left', 'auto'); rgSet(el, 'margin-right', 'auto'); }
