      c += vec3(0.95, 0.98, 1.0) * smoothstep(0.975, 0.997, dot(d, normalize(vec3(0.45, 0.85, -0.35)))) * 5.0;
      c += vec3(0.55, 0.85, 1.0) * smoothstep(0.955, 0.993, dot(d, normalize(vec3(-0.75, 0.45, -0.45)))) * 3.0;
