    // richer mechanical emoji set but explicitly exclude robot 🤖
    const mechEmojis = ['⚙️','🔩','🛠️','🔧','🪛','⚒️','🔗','🧰','🧲','🧪','📦','🔋','🧭','🧱'];
    // spawn more emojis than generic: count tuned by viewport width
    const count = 18;
    for(let i=0;i<count;i++){
      const ch = mechEmojis[Math.floor(Math.random()*mechEmojis.length)];
      const el = document.createElement('div');
      el.className = 'mechanical-emoji';
      el.textContent = ch;
      // random vertical placement (10vh .. 80vh) to create lanes
      const top = 6 + Math.random() * 78;
      el.style.top = top + 'vh';
      // stagger start times so some are already mid-run
      const dur = 8 + Math.random() * 10; // 8s..18s
      const delay = -Math.random() * 8;
      el.style.animationDuration = dur + 's';
      el.style.animationDelay = delay + 's';
      // subtle size variation
      el.style.fontSize = (14 + Math.floor(Math.random()*18)) + 'px';
      mechLayer.appendChild(el);
    }

