/* Save system with slots */
const craftState = {}; // persisted per-craft "have" counts, chosen qty, and auto-craft flag
let questState = {}; // persisted quest-line progress — declared here (not lower down where the
// quest system's other code lives) so it's already initialized by the time loadStateFromSlot
// runs; that call happens synchronously much earlier in the file than the quest code itself.

// ---- Clean crafting state API (single source of truth — no DOM-cached have/need values) ----
// craftState[craftId] = { autocraft: bool, qty: number, have: { [ingredientIndex]: number } }
function craftGetState(craftId){
  if(!craftState[craftId]) craftState[craftId] = { autocraft:false, qty:1, have:{} };
  const st = craftState[craftId];
  if(!st.have || typeof st.have !== 'object'){
    // migrate legacy save format: numeric keys used to live directly on this object
    const migratedHave = {};
    Object.keys(st).forEach(k=>{
      if(k === 'autocraft' || k === 'qty' || k === 'have') return;
      if(/^\d+$/.test(k) && typeof st[k] === 'number'){
        migratedHave[k] = st[k];
        delete st[k];
      }
    });
    st.have = migratedHave;
  }
  if(typeof st.qty !== 'number' || st.qty < 1) st.qty = 1;
  if(typeof st.autocraft !== 'boolean') st.autocraft = false;
  return st;
}
function craftGetQty(craftId){ return Math.max(1, Math.floor(craftGetState(craftId).qty)); }
function craftSetQty(craftId, qty){ craftGetState(craftId).qty = Math.max(1, Math.floor(Number(qty) || 1)); }
function craftGetHave(craftId, idx){ return craftGetState(craftId).have[idx] || 0; }
function craftSetHave(craftId, idx, val){ craftGetState(craftId).have[idx] = Math.max(0, Math.floor(val || 0)); }
function craftNeed(recipe, idx, qty){ return (recipe[idx].need || 1) * qty; }
function craftResetHave(craftId){ craftGetState(craftId).have = {}; }
function craftIsEquipment(craftId){
  const meta = ITEMS[craftId];
  return !!(meta && meta.rarity === '-');
}
function craftIsFullyStocked(entry){
  const qty = craftGetQty(entry.id);
  return entry.recipe.every((r, i) => craftGetHave(entry.id, i) >= craftNeed(entry.recipe, i, qty));
}
function craftCoinCost(entry){
  const meta = ITEMS[entry.id];
  if(typeof entry.coinCost === 'number') return entry.coinCost;
  if(meta && typeof meta.coinCost === 'number') return meta.coinCost;
  return null;
}

// Places up to `amount` units of `sourceId` into whichever ingredient slot(s) of `entry`'s
// recipe accept it, pulling from inventory/POTIONS. This is the ONLY place that moves
// ingredients from inventory into a craft's "have" buffer — both the manual "Положить"
// button and background auto-add call this same function, so they can never drift apart
// or double-consume.
function craftPlaceIngredient(entry, sourceId, amount, fromInventory = true){
  const craftId = entry.id;
  const qty = craftGetQty(craftId);
  let placed = 0;
  for(let i=0; i<entry.recipe.length && placed < amount; i++){
    if(entry.recipe[i].id !== sourceId) continue;
    const need = craftNeed(entry.recipe, i, qty);
    let have = craftGetHave(craftId, i);
    while(have < need && placed < amount){
      if(fromInventory){
        // manual "Положить": pull one unit out of existing inventory/potions stock
        if(availableCountFor(sourceId) <= 0) break;
        if(sourceId && POTIONS[sourceId] && typeof POTIONS[sourceId].count === 'number'){
          POTIONS[sourceId].count = Math.max(0, POTIONS[sourceId].count - 1);
        } else {
          ensureItem(sourceId);
          inventory[sourceId].count = Math.max(0, (inventory[sourceId].count || 0) - 1);
        }
      }
      // else: auto-add intercepts a value that just dropped and was never added to
      // inventory in the first place — nothing to deduct, just credit the have-counter.
      have += 1;
      placed += 1;
    }
    craftSetHave(craftId, i, have);
  }
  return placed;
}

// Atomically finishes a craft: validates EVERYTHING first (equipment-already-owned,
// ingredients fully stocked, coins affordable) with zero side effects, and only mutates
// state once every check has passed — this is what fixes "ingredients consumed but nothing
// granted": under the old code, ingredients could be deducted from inventory before the
// output was granted, with no guarantee both halves happened together.
function craftExecute(entry){
  const craftId = entry.id;
  const qty = craftGetQty(craftId);

  if(craftIsEquipment(craftId) && inventory[craftId] && inventory[craftId].count > 0){
    window.alert('У тебя уже есть этот предмет снаряжения — скрафтить ещё одну копию нельзя.');
    return false;
  }
  if(!craftIsFullyStocked(entry)){
    window.alert('Не хватает ингредиентов.');
    return false;
  }
  const coinCost = craftCoinCost(entry);
  const totalCost = coinCost ? coinCost * qty : 0;
  if(totalCost > 0 && coins < totalCost){
    window.alert(`Недостаточно монет. Нужно ${totalCost} 🪙.`);
    return false;
  }

  // --- validated: perform the whole thing now, nothing here can fail partway ---
  if(totalCost > 0){
    coins = Math.max(0, coins - totalCost);
    updateCoinDisplay(true);
  }

  // consume exactly what this craft needs from each ingredient's have-buffer — any surplus
  // (e.g. you'd placed 30 but only needed 10 for this batch) stays banked for next time,
  // instead of being wiped out entirely.
  entry.recipe.forEach((r, i)=>{
    const need = craftNeed(entry.recipe, i, qty);
    const have = craftGetHave(craftId, i);
    craftSetHave(craftId, i, have - need);
  });

  if(entry.id in POTIONS){
    POTIONS[entry.id].count = (POTIONS[entry.id].count || 0) + qty;
  } else {
    ensureItem(entry.id);
    inventory[entry.id].count += qty;
    inventory[entry.id].times += qty;
    recordPulls(entry.id, qty);
    try{
      if(typeof window._seenItems === 'undefined') window._seenItems = {};
      window._seenItems[entry.id] = true;
    }catch(e){}
  }

  renderInventory();
  briefResultMessage(`${styledRarityName(entry.id, entry.name)} создан x${qty}`);
  saveState();
  return true;
}
let currentSaveSlot = 1; // default slot
const MAX_SAVE_SLOTS = 1;

// Bank system for auto-collector
let bankCoins = 0;
let bankLevel = 0; // Bank upgrade level: 0 = starting (free), 1 = original behavior (300🪙),
// 2 = doubled amount (2000🪙), 3 = doubles collection SPEED instead of amount (10000🪙)
const BANK_MAX_BY_LEVEL = [5000, 10000, 20000, 30000];
function getBankMax(){
  const lvl = Math.max(0, Math.min(bankLevel, BANK_MAX_BY_LEVEL.length - 1));
  return BANK_MAX_BY_LEVEL[lvl];
}
function getBankIncomeBase(){
  if(bankLevel <= 0) return 1; // level 0: reduced income
  // amount only doubles from level 1 -> 2; level 3 doesn't add more per-tick, it instead
  // halves the coin-spawn interval (see getBankSpeedMultiplier / scheduleNextSpawn)
  return 2 * Math.pow(2, Math.min(bankLevel, 2) - 1);
}
function getBankSpeedMultiplier(){
  return bankLevel >= 3 ? 2 : 1;
}
if(typeof window.autoCollectorActive === 'undefined') window.autoCollectorActive = false;

function getSaveKey(slot){
  return `spin_save_slot_${slot}_v1`;
}

function loadStateFromSlot(slot){
  try{
    const raw = localStorage.getItem(getSaveKey(slot));
    if(!raw) return;
    const state = JSON.parse(raw);

    if(typeof state.coins === 'number') coins = state.coins;
    if(typeof state.inventoryMaxSlots === 'number') inventoryMaxSlots = state.inventoryMaxSlots;
    if(typeof state.expansionPrice === 'number') expansionPrice = state.expansionPrice;
    if(typeof state.skipperActive === 'boolean') skipperActive = state.skipperActive;
    if(typeof state.pigGloveActive === 'boolean') window.pigGloveActive = state.pigGloveActive;
    if(typeof state.richGloveActive === 'boolean') window.richGloveActive = state.richGloveActive;
    if(typeof state.friendsGloveActive === 'boolean') window.friendsGloveActive = state.friendsGloveActive;
    if(typeof state.zombieGloveActive === 'boolean') window.zombieGloveActive = state.zombieGloveActive;
    if(typeof state.volcanicGloveActive === 'boolean') window.volcanicGloveActive = state.volcanicGloveActive;
    if(typeof state.lightningGloveActive === 'boolean') window.lightningGloveActive = state.lightningGloveActive;
    if(typeof state.rainbowGloveActive === 'boolean') window.rainbowGloveActive = state.rainbowGloveActive;
    if(typeof state.cloverGloveActive === 'boolean') window.cloverGloveActive = state.cloverGloveActive;
    if(typeof state.ghostGloveActive === 'boolean') window.ghostGloveActive = state.ghostGloveActive;
    if(typeof state.luckyGloveActive === 'boolean') window.luckyGloveActive = state.luckyGloveActive;
    if(typeof state.autoCollectorActive === 'boolean') window.autoCollectorActive = state.autoCollectorActive;
    if(typeof state.bankCoins === 'number') bankCoins = state.bankCoins;
    if(typeof state.bankLevel === 'number') bankLevel = state.bankLevel;

    // Equipment active-flags are now restored above, but the actual speed/luck bonuses
    // they grant were previously only ever (re-)applied inside each toggle button's click
    // handler — meaning a glove that was left ON in a saved game did nothing until the
    // player switched it off and back on. Recompute immediately so loaded state takes
    // effect right away.
    if(typeof recomputeEquipmentEffects === 'function') recomputeEquipmentEffects();

    if(typeof state.activeThemeId === 'string') activeThemeId = state.activeThemeId;
    if(typeof state.totalSpins === 'number') totalSpins = state.totalSpins;
    if(typeof state.totalPlaytimeMinutes === 'number') totalPlaytimeMinutes = state.totalPlaytimeMinutes;
    if(typeof state.biomeChangerCooldownMs === 'number' && state.biomeChangerCooldownMs > 0) window._biomeChangerCooldownMs = state.biomeChangerCooldownMs;
    // Изменитель биома's cooldown is never persisted across reloads on purpose — the
    // timer always restarts fresh from full length right here, every time the page
    // loads. Without this, someone mid-cooldown could reload to instantly bypass the
    // wait (since _biomeChangerReadyAt only ever lived in memory); always resetting to
    // a full fresh cooldown makes reloading strictly never advantageous.
    window._biomeChangerReadyAt = Date.now() + (window._biomeChangerCooldownMs || (15 * 60 * 1000));
    if(typeof state.spinsSinceBonus === 'number') spinsSinceBonus = state.spinsSinceBonus;
    if(typeof state.nextSpinBonusMultiplier === 'number') nextSpinBonusMultiplier = state.nextSpinBonusMultiplier;
    if(typeof state.keepThreshold === 'number') keepThreshold = state.keepThreshold;
    // restore filter state
    if(state.filterState && typeof state.filterState === 'object'){
      window._filterState = state.filterState || {};
    }
    // restore seen items used by the Filter (values you've ever rolled)
    if(state.seenItems && typeof state.seenItems === 'object'){
      window._seenItems = state.seenItems || {};
    }
    
    // restore weather filter state
    if(state.weatherFilterState && typeof state.weatherFilterState === 'object'){
      window._weatherFilterState = state.weatherFilterState || {};
    }

    // If player already reached 200+ spins in saved state, auto-spin becomes available to use —
    // but whether it's actually ON depends on the player's own saved preference below, not this.
    if(typeof totalSpins === 'number' && totalSpins >= 200){
      autoSpinUnlocked = true;
    }

    if(state.inventory && typeof state.inventory === 'object'){
      Object.keys(state.inventory).forEach(k=>{
        ensureItem(k);
        inventory[k].count = Number(state.inventory[k].count || 0);
        inventory[k].times = Number(state.inventory[k].times || 0);
        inventory[k].pulls = Array.isArray(state.inventory[k].pulls) ? state.inventory[k].pulls : [];
      });
      normalizeInventoryPulls();
    }

    if(state.POTIONS && typeof state.POTIONS === 'object'){
      Object.keys(state.POTIONS).forEach(k=>{
        if(POTIONS[k]) POTIONS[k].count = Number(state.POTIONS[k].count || 0);
      });
    }

    if(state.craftState && typeof state.craftState === 'object'){
      Object.keys(state.craftState).forEach(k=>{
        craftState[k] = state.craftState[k];
      });
    }

    if(state.questState && typeof state.questState === 'object'){
      Object.keys(state.questState).forEach(k=>{
        questState[k] = state.questState[k];
      });
    }

    if(typeof state.breweryUnlocked === 'boolean'){
      window.breweryUnlocked = state.breweryUnlocked;
      if(typeof updateBreweryButtonVisibility === 'function') updateBreweryButtonVisibility();
    }

    // restore activeEffects: each saved effect stored remainingMs; re-create activeEffects entries and schedule removals
    if(state.activeEffects && typeof state.activeEffects === 'object'){
      const now = Date.now();
      Object.keys(state.activeEffects).forEach(aid=>{
        const rem = Number(state.activeEffects[aid] || 0);
        if(rem > 0 && POTIONS[aid]){
          activeEffects[aid] = { expiresAt: now + rem, timeoutId: null, intervalId: null };
          showEffectIcon({ id: aid, name: POTIONS[aid].effectName || POTIONS[aid].name, desc: POTIONS[aid].desc, color: POTIONS[aid].color });
          recomputePotionSpeedMultiplier();
          scheduleEffectRemoval(aid);
        }
      });
    }

    // restore auto-spin unlocked / enabled state if present
    if(typeof state.autoSpinUnlocked === 'boolean') autoSpinUnlocked = state.autoSpinUnlocked;
    if(typeof state.autoSpinEnabled === 'boolean') autoSpinEnabled = state.autoSpinEnabled;

    // if auto-spin was enabled when saved, start the checker loop again
    if(autoSpinEnabled){
      if(autoSpinCheckerId) BGClock.clear(autoSpinCheckerId);
      autoSpinCheckerId = BGClock.interval(()=>{
        if(autoSpinEnabled && !spinBtn.disabled){
          showPreviewsThenReveal();
        }
      }, 300);
    }

    // if theme was active previously, reapply minimal UI
    if(activeThemeId) applyThemeForItem(activeThemeId);

    // update visuals for auto-spin button to reflect restored state
    updateAutoSpinButton();
  }catch(e){
    console.warn('Failed to load state', e);
  }
}

function saveStateToSlot(slot){
  // a wipe is in progress: never write the old state back (autosave / beforeunload)
  if(window._wipingProgress) return;
  try{
    const state = {
      coins,
      inventoryMaxSlots,
      expansionPrice,
      skipperActive: !!skipperActive,
      pigGloveActive: !!window.pigGloveActive,
      richGloveActive: !!window.richGloveActive,
      friendsGloveActive: !!window.friendsGloveActive,
      zombieGloveActive: !!window.zombieGloveActive,
      volcanicGloveActive: !!window.volcanicGloveActive,
      lightningGloveActive: !!window.lightningGloveActive,
      rainbowGloveActive: !!window.rainbowGloveActive,
      cloverGloveActive: !!window.cloverGloveActive,
      ghostGloveActive: !!window.ghostGloveActive,
      luckyGloveActive: !!window.luckyGloveActive,
      autoCollectorActive: !!window.autoCollectorActive,
      bankCoins: bankCoins || 0,
      bankLevel: (typeof bankLevel === 'number') ? bankLevel : 0,

      activeThemeId: activeThemeId || null,
      totalSpins: totalSpins || 0,
      totalPlaytimeMinutes: totalPlaytimeMinutes || 0,
      biomeChangerCooldownMs: window._biomeChangerCooldownMs || (15 * 60 * 1000),
      spinsSinceBonus: spinsSinceBonus || 0,
      nextSpinBonusMultiplier: nextSpinBonusMultiplier || 1,
      keepThreshold: typeof keepThreshold === 'number' ? keepThreshold : 0,
      autoSpinUnlocked: !!autoSpinUnlocked,
      autoSpinEnabled: !!autoSpinEnabled,
      inventory: {},
      POTIONS: {},
      craftState: craftState || {},
      questState: questState || {},
      breweryUnlocked: !!window.breweryUnlocked,
      activeEffects: {}
    };

    Object.keys(inventory).forEach(k=>{
      const v = inventory[k];
      if(v && (v.count > 0 || v.times > 0)){
        state.inventory[k] = { count: v.count, times: v.times, pulls: Array.isArray(v.pulls) ? v.pulls : [] };
      }
    });

    Object.keys(POTIONS).forEach(k=>{
      state.POTIONS[k] = { count: Number(POTIONS[k].count || 0) };
    });

    // persist activeEffects as remaining milliseconds from now
    const now = Date.now();
    Object.keys(activeEffects).forEach(aid=>{
      const info = activeEffects[aid];
      if(info && info.expiresAt){
        const rem = Math.max(0, info.expiresAt - now);
        state.activeEffects[aid] = rem;
      }
    });

    // persist filter state and seen items (values that have appeared at least once)
    state.filterState = window._filterState || {};
    state.seenItems = window._seenItems || {};
    state.weatherFilterState = window._weatherFilterState || {};
    state.savedAt = Date.now();
    localStorage.setItem(getSaveKey(slot), JSON.stringify(state));
    localStorage.setItem('spin_current_slot', String(slot));
  }catch(e){
    console.warn('Failed to save state', e);
  }
}

function loadState(){
  // Try to load from current slot
  const savedSlot = localStorage.getItem('spin_current_slot');
  if(savedSlot) currentSaveSlot = Number(savedSlot) || 1;
  loadStateFromSlot(currentSaveSlot);
}

function saveState(){
  saveStateToSlot(currentSaveSlot);
}

function getSaveSlotInfo(slot){
  const raw = localStorage.getItem(getSaveKey(slot));
  if(!raw) return null;
  try{
    const data = JSON.parse(raw);
    return {
      exists: true,
      savedAt: data.savedAt || null,
      coins: data.coins || 0,
      totalSpins: data.totalSpins || 0
    };
  }catch(e){
    return null;
  }
}

// Generic, reusable confirm modal (native window.confirm() is unreliable inside
// sandboxed preview iframes — same reasoning as the wipe-progress confirm). Pass the
// message to show and a callback that runs only if the player picks "Да".
const genericConfirmModal = document.getElementById('generic-confirm-modal');
const genericConfirmText = document.getElementById('generic-confirm-text');
const genericConfirmYesBtn = document.getElementById('generic-confirm-yes');
const genericConfirmNoBtn = document.getElementById('generic-confirm-no');
function showGenericConfirm(message, onYes){
  if(!genericConfirmModal || !genericConfirmText || !genericConfirmYesBtn || !genericConfirmNoBtn) return;
  genericConfirmText.textContent = message;
  genericConfirmModal.setAttribute('aria-hidden', 'false');
  const cleanup = ()=>{
    genericConfirmModal.setAttribute('aria-hidden', 'true');
    genericConfirmYesBtn.onclick = null;
    genericConfirmNoBtn.onclick = null;
  };
  genericConfirmYesBtn.onclick = ()=>{ cleanup(); if(typeof onYes === 'function') onYes(); };
  genericConfirmNoBtn.onclick = cleanup;
}
if(genericConfirmModal){
  genericConfirmModal.addEventListener('click', (e)=>{
    if(e.target === genericConfirmModal){
      genericConfirmModal.setAttribute('aria-hidden', 'true');
      genericConfirmYesBtn.onclick = null;
      genericConfirmNoBtn.onclick = null;
    }
  });
}

function deleteSaveSlot(slot){
  localStorage.removeItem(getSaveKey(slot));
  if(currentSaveSlot === slot){
    currentSaveSlot = 1;
    localStorage.setItem('spin_current_slot', '1');
  }
}

// Save modal UI
const saveBtn = document.getElementById('save-btn');
const saveModal = document.getElementById('save-modal');
const saveClose = document.getElementById('save-close');
const saveSlotsContainer = document.getElementById('save-slots');
const currentSlotNameEl = document.getElementById('current-slot-name');

// Custom confirmation modal for the destructive wipe — native window.confirm() is
// unreliable (often silently blocked, returning false immediately) inside sandboxed
// preview iframes, which is why the delete button previously did nothing at all.
const wipeConfirmModal = document.getElementById('wipe-confirm-modal');
const wipeConfirmCheckbox = document.getElementById('wipe-confirm-checkbox');
const wipeConfirmDeleteBtn = document.getElementById('wipe-confirm-delete');
const wipeConfirmCancelBtn = document.getElementById('wipe-confirm-cancel');
const wipeConfirmCloseBtn = document.getElementById('wipe-confirm-close');
let wipeCountdownTimer = null;

function closeWipeConfirmModal(){
  if(wipeConfirmModal) wipeConfirmModal.setAttribute('aria-hidden', 'true');
  if(wipeCountdownTimer){ clearInterval(wipeCountdownTimer); wipeCountdownTimer = null; }
  if(wipeConfirmCheckbox) wipeConfirmCheckbox.checked = false;
  if(wipeConfirmDeleteBtn){
    wipeConfirmDeleteBtn.disabled = true;
    wipeConfirmDeleteBtn.textContent = 'Удалить всё';
  }
}

function openWipeConfirmModal(){
  if(!wipeConfirmModal) return;
  wipeConfirmModal.setAttribute('aria-hidden', 'false');
  if(wipeConfirmCheckbox) wipeConfirmCheckbox.checked = false;
  if(wipeConfirmDeleteBtn){
    wipeConfirmDeleteBtn.disabled = true;
    wipeConfirmDeleteBtn.textContent = 'Удалить всё';
  }
}

if(wipeConfirmCheckbox){
  wipeConfirmCheckbox.addEventListener('change', ()=>{
    if(wipeCountdownTimer){ clearInterval(wipeCountdownTimer); wipeCountdownTimer = null; }
    if(!wipeConfirmCheckbox.checked || !wipeConfirmDeleteBtn){
      if(wipeConfirmDeleteBtn){
        wipeConfirmDeleteBtn.disabled = true;
        wipeConfirmDeleteBtn.textContent = 'Удалить всё';
      }
      return;
    }
    // short countdown before the button becomes clickable — a deliberate speed bump
    // against misclicks, now that this isn't gated behind three native confirm() popups
    let remaining = 3;
    wipeConfirmDeleteBtn.disabled = true;
    wipeConfirmDeleteBtn.textContent = `Удалить всё (${remaining})`;
    wipeCountdownTimer = setInterval(()=>{
      remaining -= 1;
      if(remaining <= 0){
        clearInterval(wipeCountdownTimer);
        wipeCountdownTimer = null;
        wipeConfirmDeleteBtn.disabled = false;
        wipeConfirmDeleteBtn.textContent = 'Удалить всё';
      } else {
        wipeConfirmDeleteBtn.textContent = `Удалить всё (${remaining})`;
      }
    }, 700);
  });
}
if(wipeConfirmDeleteBtn){
  wipeConfirmDeleteBtn.addEventListener('click', ()=>{
    if(wipeConfirmDeleteBtn.disabled) return;
    closeWipeConfirmModal();
    wipeAllProgress();
  });
}
if(wipeConfirmCancelBtn) wipeConfirmCancelBtn.addEventListener('click', closeWipeConfirmModal);
if(wipeConfirmCloseBtn) wipeConfirmCloseBtn.addEventListener('click', closeWipeConfirmModal);
if(wipeConfirmModal){
  wipeConfirmModal.addEventListener('click', (e)=>{
    if(e.target === wipeConfirmModal) closeWipeConfirmModal();
  });
}

function wipeAllProgress(){
  window._wipingProgress = true;
  // A real, total wipe: clear every browser storage this game could have written to,
  // then reload the page so ALL in-memory state is rebuilt from scratch.
  //
  // The old implementation reset a hand-written list of variables one by one, which meant
  // every new feature had to remember to add itself here — anything forgotten (quest
  // progress, brewery unlock, spin charges, etc.) would silently survive a "full wipe".
  // Reloading sidesteps that class of bug entirely.
  try{
    localStorage.clear();
  }catch(e){}
  try{
    sessionStorage.clear();
  }catch(e){}
  // best-effort: drop any cached assets/service-worker caches too
  try{
    if(window.caches && caches.keys){
      caches.keys().then(names => names.forEach(n => caches.delete(n))).catch(()=>{});
    }
  }catch(e){}
  try{
    if(window.indexedDB && indexedDB.databases){
      indexedDB.databases().then(dbs=>{
        dbs.forEach(db => { if(db && db.name) indexedDB.deleteDatabase(db.name); });
      }).catch(()=>{});
    }
  }catch(e){}

  briefResultMessage('Весь прогресс удалён — перезагрузка...', 1200);
  setTimeout(()=>{
    try{
      window.location.reload();
    }catch(e){
      window.location.href = window.location.pathname;
    }
  }, 600);
}

function renderSaveSlots(){
  if(!saveSlotsContainer) return;
  saveSlotsContainer.innerHTML = '';
  
  for(let i = 1; i <= MAX_SAVE_SLOTS; i++){
    const info = getSaveSlotInfo(i);
    const slotCard = document.createElement('div');
    slotCard.className = 'save-slot' + (i === currentSaveSlot ? ' active' : '');
    
    const header = document.createElement('div');
    header.className = 'save-slot-header';
    
    const nameEl = document.createElement('div');
    nameEl.className = 'save-slot-name';
    nameEl.textContent = `Слот ${i}` + (i === currentSaveSlot ? ' (текущий)' : '');
    
    const timeEl = document.createElement('div');
    timeEl.className = 'save-slot-time';
    if(info && info.savedAt){
      const d = new Date(info.savedAt);
      timeEl.textContent = d.toLocaleString('ru-RU');
    } else {
      timeEl.textContent = 'Пусто';
    }
    
    header.appendChild(nameEl);
    header.appendChild(timeEl);
    
    if(info && info.exists){
      const details = document.createElement('div');
      details.style.fontSize = '13px';
      details.style.color = 'var(--muted)';
      details.innerHTML = `Монеты: ${info.coins} · Прокруток: ${info.totalSpins}`;
      slotCard.appendChild(header);
      slotCard.appendChild(details);
    } else {
      slotCard.appendChild(header);
    }
    
    const actions = document.createElement('div');
    actions.className = 'save-slot-actions';
    

    
    const deleteBtn = document.createElement('button');
    deleteBtn.className = 'action-btn';
    deleteBtn.style.padding = '8px 12px';
    deleteBtn.style.fontSize = '14px';
    deleteBtn.style.background = '#c91f1f';
    deleteBtn.style.color = '#fff';
    deleteBtn.textContent = 'Удалить весь прогресс';
    deleteBtn.disabled = !info || !info.exists;
    deleteBtn.addEventListener('click', ()=>{
      openWipeConfirmModal();
    });
    
    actions.appendChild(deleteBtn);
    
    slotCard.appendChild(actions);
    saveSlotsContainer.appendChild(slotCard);
  }
}

if(saveBtn){
  saveBtn.addEventListener('click', ()=>{
    saveModal.setAttribute('aria-hidden', 'false');
    renderSaveSlots();
  });
}

if(saveClose){
  saveClose.addEventListener('click', ()=>{
    saveModal.setAttribute('aria-hidden', 'true');
  });
}

if(saveModal){
  saveModal.addEventListener('click', (e)=>{
    if(e.target === saveModal) saveModal.setAttribute('aria-hidden', 'true');
  });
}

// periodical autosave and save on unload
// Autosave. Serializing the full state (inventory + every pull instance + quests + crafts)
// is one of the heavier recurring operations in the game, so this runs every 5s rather
// than every 2s — still frequent enough that a crash costs almost nothing.
setInterval(saveState, 5000);
window.addEventListener('beforeunload', saveState);

/* Auto-load the single save slot on page open/reload (single-slot behavior requested).
   Load saved state, update UI and inventory display immediately. */
// an imported save waits here until the page is fresh, so nothing can overwrite it on the way
try{
  const pend = localStorage.getItem('prk_pending_import');
  if(pend){ JSON.parse(pend); localStorage.setItem(getSaveKey(currentSaveSlot), pend); localStorage.removeItem('prk_pending_import'); window._importDone = true; }
}catch(e){ try{ localStorage.removeItem('prk_pending_import'); }catch(e2){} }
loadStateFromSlot(currentSaveSlot);
if(window._importDone) setTimeout(()=>{ try{ briefResultMessage('Сохранение загружено ✔', 3000); }catch(e){} }, 600);
// pre-build the craftables/recipes cache immediately so auto-craft can find recipes even
// if the player never opens the crafting menu this session (fixes auto-craft silently
// doing nothing right after a page reload).
try{ buildCraftablesList(); }catch(e){}
try{ syncPlaytimeQuestProgress(); }catch(e){}
updateCoinDisplay(false);
updateTopStats();
renderInventory();
if(currentSlotNameEl) currentSlotNameEl.textContent = `Слот ${currentSaveSlot}`;

// initial state
updateCoinDisplay(false);
updateTopStats();
document.body.appendChild(effectsLayer);
renderInventory();
// ensure we capture the original button texts/styles once after initial render
// so theme code can reliably restore them when clearing themes
if(window._saveButtonOriginals) window._saveButtonOriginals();

// Apply initial weather theme if no value theme is active
if(!activeThemeId){
  applyWeatherTheme();
}

/*
  Craft GUI: show list of craftable items when opening anvil; clicking an item shows its ingredients.
  Added craft/purchase options for potions and kept Skipper.
*/
const craftListContainer = document.createElement('div');
craftListContainer.className = 'craft-list';
craftListContainer.style.padding = '12px';
craftListContainer.innerHTML = ''; // will populate dynamically below



 // helper to build ingredient DOM for craft modal
 // now accepts craftId to persist "have" counts across closing/opening and supports quantity selection
// Builds the ingredient/quantity/create UI for one craftable entry. Rendering always reads
// from craftState (via the craft* API above) and never trusts DOM text as a source of truth —
// this is what fixes the whole family of desync bugs (ingredients consumed with nothing
// granted, auto-add capping at the single-unit need, qty not scaling the put-limit).
// ---- Кузница / Зельеварня: shared card pieces (icon, status) ----
const GLOVE_TINT = { lucky_glove:'#2fa74a', pig_glove:'#ff8fb0', rich_glove:'#e8b830', friends_glove:'#4fb8e0', zombie_glove:'#5aa84a',
  ghost_glove:'#c6d2e6', volcanic_glove:'#ff5a1f', lightning_glove:'#f0d030', rainbow_glove:'rainbow', clover_glove:'#1f8a3c' };
// names and badges keep their own colours in the dark vault, lifted only where they'd sink
function inkFixWithin(root, bg, target){
  if(!root) return;
  root.querySelectorAll('.vc-name, .vc-name *, .name, .name *, .rc-badge, .rc-badge *, .vcp-name, .vcp-name *, .rarity').forEach(el=>{
    if(el.dataset.ink){ el.style.removeProperty('color'); el.style.removeProperty('background-image'); delete el.dataset.ink; }
    const cs = getComputedStyle(el);
    if(cs.backgroundClip === 'text' || cs.webkitBackgroundClip === 'text'){
      // gradient lettering: lift only the stops that would vanish into the card
      const img = cs.backgroundImage;
      if(img && img !== 'none'){
        let changed = false;
        const lifted = img.replace(/rgba?\([^)]+\)/g, m=>{ const c = rgParse(m); if(c[3] < 0.05 || rgRatio(c, bg) >= target - 1) return m; changed = true; return rgStr(rgInk(c, bg, target - 1)); });
        if(changed){ el.style.setProperty('background-image', lifted, 'important'); el.dataset.ink = '1'; }
      }
      return;
    }
    if(/transparent|rgba\([^)]*,\s*0\)/.test(cs.webkitTextFillColor || '')) return;
    const fg = rgParse(cs.color);
    if(fg[3] < 0.05 || rgRatio(fg, bg) >= target) return;
    el.style.setProperty('color', rgStr(rgInk(fg, bg, target)), 'important');
    el.dataset.ink = '1';
  });
}
(function inkWatch(){
  const start = ()=>{
    const bg = [30, 41, 53, 1];
    const lists = ['inventory-list', 'special-list', 'items-list', 'equipment-list'].map(i=> document.getElementById(i)).filter(Boolean);
    let raf = 0;
    const run = ()=>{ raf = 0; lists.forEach(l=> inkFixWithin(l, bg, 4.2)); };
    const mo = new MutationObserver(()=>{ if(!raf) raf = requestAnimationFrame(run); });
    lists.forEach(l=> mo.observe(l, { childList:true }));
    const vcp = document.getElementById('vcp-name');
    if(vcp) new MutationObserver(()=> requestAnimationFrame(()=> inkFixWithin(vcp.parentElement, [27, 36, 47, 1], 4.2))).observe(vcp, { childList:true });
  };
  if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start); else start();
})();

// a small orb per aura in its own colours (the item data only has placeholder pictures)
function auraIconHTML(id, size){
  size = size || 44;
  const A = (typeof ATMOS_PRESETS !== 'undefined' && ATMOS_PRESETS[id]) || null;
  const C = (typeof ITEM_COLORS !== 'undefined' && ITEM_COLORS[id]) || null;
  const isHex = v=> typeof v === 'string' && /^#[0-9a-f]{6}$/i.test(v);
  const cls = (RARITY_CLASS_META[rarityClassKeyFor(id)] || {}).color || '#8a96a8';
  const a = (A && isHex(A.acc) && A.acc) || (C && isHex(C.fg) && C.fg) || (isHex(cls) && rgLum(rgParse(cls)) > 0.02 ? cls : '#9aa6b5');
  const b = (A && isHex(A.acc2) && A.acc2) || (C && isHex(C.bg) && C.bg) || '#ffffff';
  const emo = ({ pumpkin:'🎃' })[id] || (typeof V2_PATTERNS !== 'undefined' && V2_PATTERNS[id] && V2_PATTERNS[id][1]) || '';
  const uid = 'ag' + Math.random().toString(36).slice(2, 8);
  const k = rarityClassKeyFor(id) || '';
  const high = /incredible|super|legend|myth|divine/.test(k);
  return `<svg viewBox="0 0 44 44" width="${size}" height="${size}" aria-hidden="true">
    <defs>
      <radialGradient id="${uid}" cx="38%" cy="32%" r="70%"><stop offset="0" stop-color="${b}"/><stop offset="0.45" stop-color="${a}"/><stop offset="1" stop-color="#05060a"/></radialGradient>
      <radialGradient id="${uid}h" cx="50%" cy="50%" r="50%"><stop offset="0" stop-color="${a}" stop-opacity="0.55"/><stop offset="1" stop-color="${a}" stop-opacity="0"/></radialGradient>
    </defs>
    <circle cx="22" cy="22" r="21" fill="url(#${uid}h)"/>
    <circle cx="22" cy="22" r="13.5" fill="url(#${uid})"/>
    <ellipse cx="22" cy="22" rx="19" ry="6" fill="none" stroke="${b}" stroke-opacity="0.75" stroke-width="1.3" transform="rotate(-24 22 22)"/>
    <ellipse cx="17.5" cy="16.5" rx="4.2" ry="2.6" fill="#fff" fill-opacity="0.55" transform="rotate(-30 17.5 16.5)"/>
    ${high ? `<path d="M35 7l1.1 3 3 1.1-3 1.1L35 15.2l-1.1-3-3-1.1 3-1.1z" fill="#fff" fill-opacity="0.9"/>` : ''}
    ${emo ? `<text x="22" y="27.5" font-size="14" text-anchor="middle">${emo}</text>` : ''}
  </svg>`;
}

