  + `<path d="M31 5v8" stroke="#8a95a1" stroke-width="2.2" stroke-linecap="round"/><circle class="ws-bc-tip" cx="31" cy="4.2" r="2.8" fill="#7fffd0"/>`
  + `<rect x="7" y="11" width="30" height="35" rx="7" fill="url(#bcd-b)" stroke="rgba(0,0,0,0.5)" stroke-width="1.2"/><rect x="8.5" y="12.2" width="27" height="3" rx="1.5" fill="rgba(255,255,255,0.16)"/>`
  + `<rect x="10.5" y="15" width="23" height="15.5" rx="3.2" fill="url(#bcd-s)" stroke="rgba(0,0,0,0.55)" stroke-width="1"/>`
  + `<circle cx="18" cy="21" r="3.1" fill="#fff3a0"/><path d="M16.5 27h10.2a3 3 0 0 0 0-6 4.2 4.2 0 0 0-7.8 1.3A2.4 2.4 0 0 0 16.5 27z" fill="#effff9"/><rect class="ws-scan" x="10.5" y="15" width="23" height="1.6" fill="rgba(255,255,255,0.3)"/>`
  + `<circle cx="14.5" cy="37.5" r="2.6" fill="#ff6b5b"/><circle cx="21" cy="37.5" r="2.6" fill="#ffd36b"/><circle cx="29.5" cy="38" r="4.3" fill="#1b2026" stroke="#9aa6b2" stroke-width="1.1"/><path d="M29.5 38l2.6-2.4" stroke="#7fffd0" stroke-width="1.5" stroke-linecap="round"/><path d="M12 43.2h14" stroke="rgba(255,255,255,0.14)" stroke-width="1.2" stroke-linecap="round"/></svg>`;
function workshopIcon(entry){
  const id = entry.id;
  if(id === 'biome_changer') return BIOME_DEVICE_SVG;
  if(POTIONS[id]){
    const c = POTIONS[id].color || '#7a5cff';
    return `<svg class="ws-flask" viewBox="0 0 40 48" aria-hidden="true"><path d="M15 5h10v11l9 16a8 8 0 0 1-7 12H13a8 8 0 0 1-7-12l9-16z" fill="rgba(255,255,255,0.14)" stroke="rgba(255,255,255,0.75)" stroke-width="2" stroke-linejoin="round"/><path d="M9 30.5h22l2.6 4.7a6 6 0 0 1-5.2 8.8H11.6a6 6 0 0 1-5.2-8.8z" fill="${c}"/><path d="M9 30.5h22" stroke="rgba(255,255,255,0.5)" stroke-width="1.4"/><circle class="ws-bub" cx="16" cy="37" r="1.7" fill="#fff" opacity=".75"/><circle class="ws-bub b2" cx="23" cy="34" r="1.1" fill="#fff" opacity=".65"/><rect x="13" y="2" width="14" height="4.5" rx="2.2" fill="#c9a26a"/></svg>`;
  }
  const tint = GLOVE_TINT[id];
  if(tint){
    const fill = tint === 'rainbow' ? 'url(#ws-rb)' : tint;
    return `<svg class="ws-glove" viewBox="0 0 48 48" aria-hidden="true"><defs><linearGradient id="ws-rb" x1="0" x2="1"><stop offset="0" stop-color="#ff4d4d"/><stop offset=".25" stop-color="#ffb84d"/><stop offset=".5" stop-color="#5ee07a"/><stop offset=".75" stop-color="#4fb0ff"/><stop offset="1" stop-color="#b06bff"/></linearGradient></defs><path d="M13 41V27c-3-4-5.5-8.5-6-12-.4-2.6 2.6-4 4.3-2L15 19V9a3 3 0 0 1 6 0v10V6a3 3 0 0 1 6 0v13V8a3 3 0 0 1 6 0v12v-7a3 3 0 0 1 6 0v15c0 8-4.5 12-10 13z" fill="${fill}" stroke="rgba(0,0,0,0.35)" stroke-width="1.5" stroke-linejoin="round"/><rect x="12" y="39" width="22" height="6" rx="2" fill="rgba(0,0,0,0.28)"/><path d="M17 24c3 2 9 2 14 0" stroke="rgba(255,255,255,0.45)" stroke-width="1.6" fill="none" stroke-linecap="round"/></svg>`;
  }
  const emoji = { skipper:'⏭️', auto_collector:'🧲', biome_changer:'🌍', brewery_key:'🗝️' }[id] || (entry.category === 'values' ? '✨' : '⚙️');
  return `<span class="ws-emoji" aria-hidden="true">${emoji}</span>`;
}
// names styled in very dark colours vanish on the dark workshop cards
function workshopReadable(html){
  return html.replace(/color:\s*(#[0-9a-f]{3,8})/i, (all, hex)=>{
    let x = hex.slice(1); if(x.length === 3) x = x.split('').map(c => c + c).join('');
    const r = parseInt(x.slice(0, 2), 16), g = parseInt(x.slice(2, 4), 16), b = parseInt(x.slice(4, 6), 16);
    const l = (0.2126 * r + 0.7152 * g + 0.0722 * b) / 255;
    if(l >= 0.42) return all;
    const k = l < 0.12 ? 0.82 : 0.55; // lift toward white, keep the hue
    const f = (v)=> Math.round(v + (255 - v) * k).toString(16).padStart(2, '0');
    return 'color:#' + f(r) + f(g) + f(b);
  });
}
function workshopStatus(entry){
  const isEq = craftIsEquipment(entry.id);
  if(isEq && inventory[entry.id] && inventory[entry.id].count > 0) return { cls:'own', text:'Уже есть' };
  if(entry.type === 'buy') return { cls:'buy', text:`${entry.price} 🪙` };
  const recipe = entry.recipe || [];
  if(!recipe.length) return { cls:'prog', text:'Крафт' };
  const qty = craftGetQty(entry.id);
  let done = 0;
  recipe.forEach((r, i)=>{ if(craftGetHave(entry.id, i) >= craftNeed(recipe, i, qty)) done++; });
  if(done === recipe.length) return { cls:'ready', text:'Можно создать' };
  return { cls:'prog', text:`${done} из ${recipe.length}`, pct: done / recipe.length };
}
function workshopEffects(desc){
  if(!desc) return '';
  return desc.split(/\s*[·;]\s*|,\s+(?=[+x×\d])/).filter(Boolean).map(t=> `<span class="ws-chip">${t}</span>`).join('');
}
function workshopHeadHTML(entry, displayName){
  return `<div class="ws-head">
      <div class="ws-icon">${workshopIcon(entry)}</div>
      <div class="ws-main"><div class="name ws-name">${displayName}</div><div class="ws-chips">${workshopEffects(entry.effectDesc) || `<span class="ws-chip ws-chip-muted">${entry.type === 'buy' ? 'Покупка за монеты' : 'Крафт'}</span>`}</div></div>
      <div class="ws-status"></div>
      <button class="craft-toggle-btn ws-toggle" type="button" aria-label="Открыть рецепт">▾</button>
    </div>`;
}
function workshopRefreshStatus(card, entry){
  const el = card.querySelector('.ws-status'); if(!el) return;
  const st = workshopStatus(entry);
  el.className = 'ws-status ws-' + st.cls;
  el.innerHTML = st.pct !== undefined ? `<span class="ws-ring" style="--p:${st.pct}"></span>${st.text}` : st.text;
  card.classList.toggle('ws-is-ready', st.cls === 'ready');
  card.classList.toggle('ws-is-own', st.cls === 'own');
}

function buildCraftIngredientsUI(entry){
  const craftId = entry.id;
  const recipe = entry.recipe;
  const isEquipment = craftIsEquipment(craftId);
  // equipment can only ever be owned once, so batch-crafting more than 1 makes no sense —
  // cap it here instead of special-casing just "skipper" like before.
  if(isEquipment) craftSetQty(craftId, 1);

  const container = document.createElement('div');
  container.className = 'craft-ingredients-dynamic';
  container.dataset.craftId = craftId;
  container.style.display = 'grid';
  container.style.gridTemplateColumns = 'repeat(auto-fill, minmax(230px, 1fr))';
  container.style.gap = '8px';
  container.style.marginTop = '12px';

  const rows = recipe.map((r, idx)=>{
    const row = document.createElement('div');
    row.className = 'ingredient ingredient-compact';
    row.style.display = 'flex';
    row.style.justifyContent = 'space-between';
    row.style.alignItems = 'center';
    row.style.flexWrap = 'wrap';

    const left = document.createElement('div');
    left.className = 'ing-left';
    left.innerHTML = `<strong>${workshopReadable(styledRarityName(r.id, r.name))}</strong>`;

    const right = document.createElement('div');
    right.className = 'ing-right';
    const haveSpan = document.createElement('span');
    haveSpan.className = 'ing-have';
    const needSpan = document.createElement('span');
    needSpan.className = 'ing-need';

    const putQtyInput = document.createElement('input');
    putQtyInput.className = 'ing-put-qty';
    putQtyInput.type = 'number';
    putQtyInput.min = '1';
    putQtyInput.value = '1';
    putQtyInput.title = 'Сколько положить за раз';

    const putBtn = document.createElement('button');
    putBtn.className = 'ing-put';
    putBtn.textContent = 'Положить';
    putBtn.style.padding = '6px 8px';
    putBtn.style.borderRadius = '8px';
    putBtn.style.border = '0';
    putBtn.style.background = 'var(--accent)';
    putBtn.style.color = '#fff';
    putBtn.dataset.id = r.id || '';

    const putMaxBtn = document.createElement('button');
    putMaxBtn.className = 'ing-put ing-put-max';
    putMaxBtn.textContent = 'МАКС';
    putMaxBtn.style.padding = '6px 8px';
    putMaxBtn.style.borderRadius = '8px';
    putMaxBtn.style.border = '0';
    putMaxBtn.style.background = '#5a6270';
    putMaxBtn.style.color = '#fff';

    right.appendChild(haveSpan);
    right.appendChild(document.createTextNode(' / '));
    right.appendChild(needSpan);
    right.appendChild(putQtyInput);
    right.appendChild(putBtn);
    right.appendChild(putMaxBtn);
    row.appendChild(left);
    row.appendChild(right);
    container.appendChild(row);

    // Shared by both buttons: craftPlaceIngredient already stops at whichever limit comes
    // first (remaining need, or how many the player actually owns), so an oversized amount
    // here can never over-place or consume more than it should.
    function placeAmount(amount){
      const want = Math.max(1, Math.floor(Number(amount) || 1));
      const placedCount = craftPlaceIngredient(entry, r.id, want);
      if(placedCount > 0){
        renderInventory();
        saveState();
      }
      render();
    }

    putBtn.addEventListener('click', ()=> placeAmount(putQtyInput.value));
    putMaxBtn.addEventListener('click', ()=>{
      // "as much as still fits" — the helper clamps to stock automatically
      const qty = craftGetQty(craftId);
      const stillNeeded = Math.max(0, craftNeed(recipe, idx, qty) - craftGetHave(craftId, idx));
      if(stillNeeded > 0) placeAmount(stillNeeded);
    });

    return { row, haveSpan, needSpan, putBtn, putMaxBtn, putQtyInput };
  });

  // quantity row (how many batches to craft) — hidden entirely for equipment, since it's
  // always exactly 1 and a visible "Кол-во: 1" locked field just adds confusion
  const qtyRow = document.createElement('div');
  qtyRow.style.display = 'flex';
  qtyRow.style.justifyContent = 'flex-end';
  qtyRow.style.alignItems = 'center';
  qtyRow.style.gap = '8px';
  qtyRow.style.marginTop = '6px';
  qtyRow.style.gridColumn = '1 / -1';

  const qtyInput = document.createElement('input');
  if(!isEquipment){
    const qtyLabel = document.createElement('label');
    qtyLabel.style.fontSize = '13px';
    qtyLabel.style.color = 'var(--muted)';
    qtyLabel.textContent = 'Кол-во:';
    qtyInput.type = 'number';
    qtyInput.min = '1';
    qtyInput.style.width = '72px';
    qtyInput.style.padding = '6px';
    qtyInput.style.borderRadius = '8px';
    qtyInput.style.border = '1px solid #ddd';
    qtyRow.appendChild(qtyLabel);
    qtyRow.appendChild(qtyInput);
    container.appendChild(qtyRow);

    qtyInput.addEventListener('input', ()=>{
      craftSetQty(craftId, qtyInput.value);
      render();
    });
  }

  // actions row (Create)
  const actionsRow = document.createElement('div');
  actionsRow.style.display = 'flex';
  actionsRow.style.justifyContent = 'flex-end';
  actionsRow.style.gap = '8px';
  actionsRow.style.marginTop = '8px';
  actionsRow.style.gridColumn = '1 / -1';

  const createBtn = document.createElement('button');
  createBtn.className = 'action-btn theme-rounded';
  createBtn.style.padding = '12px 18px';
  createBtn.style.minWidth = '140px';
  createBtn.style.fontSize = '16px';
  createBtn.style.background = 'var(--accent)';
  createBtn.style.color = '#fff';
  actionsRow.appendChild(createBtn);
  container.appendChild(actionsRow);

  if(craftId === 'auto_collector'){
    const note = document.createElement('div');
    note.style.marginTop = '6px';
    note.style.fontSize = '13px';
    note.style.color = 'var(--muted)';
    note.style.gridColumn = '1 / -1';
    note.textContent = 'Цена сборки 100 🪙';
    container.appendChild(note);
  }

  createBtn.addEventListener('click', ()=>{
    craftExecute(entry);
    render();
  });

  // single render function — the ONLY place that writes have/need text and button state,
  // always computed fresh from craftState. Exposed on the container so background auto-add
  // can trigger a repaint if this card happens to be open.
  function render(){
    const qty = craftGetQty(craftId);
    if(!isEquipment) qtyInput.value = String(qty);

    const alreadyOwned = isEquipment && inventory[craftId] && inventory[craftId].count > 0;

    let allMet = !alreadyOwned;
    rows.forEach((ui, idx)=>{
      const need = craftNeed(recipe, idx, qty);
      const have = craftGetHave(craftId, idx);
      ui.haveSpan.textContent = String(have);
      ui.needSpan.textContent = String(need);
      ui.row.style.setProperty('--pct', String(Math.min(1, need ? have / need : 1)));
      ui.row.classList.toggle('ing-done', have >= need);
      if(have < need) allMet = false;
      const putDisabled = alreadyOwned || availableCountFor(recipe[idx].id) <= 0 || have >= need;
      ui.putBtn.disabled = putDisabled;
      if(ui.putMaxBtn) ui.putMaxBtn.disabled = putDisabled;
      if(ui.putQtyInput) ui.putQtyInput.disabled = putDisabled;
    });

    const coinCost = craftCoinCost(entry);
    const totalCost = coinCost ? coinCost * qty : 0;
    createBtn.textContent = coinCost ? `Создать (${totalCost}🪙)` : 'Создать';
    createBtn.disabled = !allMet || (totalCost > 0 && coins < totalCost);
    createBtn.classList.toggle('ws-ready-btn', !createBtn.disabled);
    try{ container.dispatchEvent(new CustomEvent('craft-progress', { bubbles:true })); }catch(e){}
  }
  container._craftRender = render;
  render();

  return container;
}


