 function getQuestState(lineId){
   if(!questState[lineId]) questState[lineId] = { questIndex: 0, progress: {} };
   return questState[lineId];
 }
 function getTaskProgress(lineId, questIndex, taskIndex){
   const st = getQuestState(lineId);
   if(!st.progress[questIndex]) return 0;
   return st.progress[questIndex][taskIndex] || 0;
 }
 function bumpTaskProgress(lineId, questIndex, taskIndex, target){
   const st = getQuestState(lineId);
   if(!st.progress[questIndex]) st.progress[questIndex] = {};
   const cur = st.progress[questIndex][taskIndex] || 0;
   if(cur >= target) return false;
   st.progress[questIndex][taskIndex] = cur + 1;
   return true;
 }
 function isQuestReady(lineId, questIndex, quest){
   return quest.tasks.every((task, taskIndex)=> getTaskProgress(lineId, questIndex, taskIndex) >= task.target);
 }

 // Called for every roll result (regardless of keep/skip/auto-craft) so "Выбей N аур"-style
 // tasks track actual drops, matching how "Выпадало" is understood elsewhere in the game.
 function trackQuestProgress(item){
   if(!item || !item.id) return;
   const rc = rarityClassKeyFor(item.id);
   let changed = false;
   Object.keys(QUEST_LINES).forEach(lineId=>{
     const line = QUEST_LINES[lineId];
     const st = getQuestState(lineId);
     const quest = line.quests[st.questIndex];
     if(!quest) return;
     quest.tasks.forEach((task, taskIndex)=>{
       if(task.type === 'rarityClass' && rc && rc === task.rarityClass){
         if(bumpTaskProgress(lineId, st.questIndex, taskIndex, task.target)) changed = true;
       } else if(task.type === 'specificAura' && item.id === task.auraId){
         if(bumpTaskProgress(lineId, st.questIndex, taskIndex, task.target)) changed = true;
       }
     });
   });
   if(changed){
     renderQuestsUI();
     saveState();
   }
 }

 // Called whenever the player actually uses potions (see the "Применить" button in the
 // inventory), so "Используй N зелий" tasks count real usage, any potion type combined.
 // Also bumps "specificPotionUse" tasks (e.g. "Используй Летнее Зелье x10") when the used
 // potion's id matches.
 function trackQuestPotionUse(qty, potionId){
   if(!qty || qty <= 0) return;
   let changed = false;
   Object.keys(QUEST_LINES).forEach(lineId=>{
     const line = QUEST_LINES[lineId];
     const st = getQuestState(lineId);
     const quest = line.quests[st.questIndex];
     if(!quest) return;
     quest.tasks.forEach((task, taskIndex)=>{
       if(task.type === 'potionUse'){
         for(let i=0;i<qty;i++){
           if(bumpTaskProgress(lineId, st.questIndex, taskIndex, task.target)) changed = true;
         }
       } else if(task.type === 'specificPotionUse' && potionId && task.potionId === potionId){
         for(let i=0;i<qty;i++){
           if(bumpTaskProgress(lineId, st.questIndex, taskIndex, task.target)) changed = true;
         }
       }
     });
   });
   if(changed){
     renderQuestsUI();
     saveState();
   }
 }

 // Called whenever Изменитель биома successfully rolls a new weather — bumps any
 // "biomeChangerWeather" task whose target weather matches what was just rolled.
 function trackBiomeChangerWeather(weatherName){
   if(!weatherName) return;
   let changed = false;
   Object.keys(QUEST_LINES).forEach(lineId=>{
     const line = QUEST_LINES[lineId];
     const st = getQuestState(lineId);
     const quest = line.quests[st.questIndex];
     if(!quest) return;
     quest.tasks.forEach((task, taskIndex)=>{
       if(task.type === 'biomeChangerWeather' && task.weatherName === weatherName){
         if(bumpTaskProgress(lineId, st.questIndex, taskIndex, task.target)) changed = true;
       }
     });
   });
   if(changed){
     renderQuestsUI();
     saveState();
   }
 }

 // "Пробудь в игре N минут" tasks track a continuously-known value (not a discrete event),
 // so this directly sets progress from totalPlaytimeMinutes instead of incrementing it.
 function syncPlaytimeQuestProgress(){
   let changed = false;
   Object.keys(QUEST_LINES).forEach(lineId=>{
     const line = QUEST_LINES[lineId];
     const st = getQuestState(lineId);
     const quest = line.quests[st.questIndex];
     if(!quest) return;
     quest.tasks.forEach((task, taskIndex)=>{
       if(task.type !== 'playtime') return;
       if(!st.progress[st.questIndex]) st.progress[st.questIndex] = {};
       const cur = st.progress[st.questIndex][taskIndex] || 0;
       const next = Math.min(task.target, totalPlaytimeMinutes);
       if(next > cur){
         st.progress[st.questIndex][taskIndex] = next;
         changed = true;
       }
     });
   });
   if(changed){
     renderQuestsUI();
     saveState();
   }
 }

 const questsBtn = document.getElementById('quests-btn');
 const questsModal = document.getElementById('quests-modal');
 const questsClose = document.getElementById('quests-close');
 const questsBody = document.getElementById('quests-body');
 const questsHeaderTitle = document.getElementById('quests-header-title');
 let questsView = { screen: 'list', lineId: null };

 function openQuestsModal(){
   questsView = { screen: 'list', lineId: null };
   if(questsModal) questsModal.setAttribute('aria-hidden', 'false');
   try{ syncPlaytimeQuestProgress(); }catch(e){}
   renderQuestsUI();
 }
 function closeQuestsModal(){
   if(questsModal) questsModal.setAttribute('aria-hidden', 'true');
 }

 // Re-renders whichever screen is currently showing — safe to call any time (e.g. from
 // progress tracking) since it no-ops while the modal is closed.
 function renderQuestsUI(){
   if(!questsModal || !questsBody || questsModal.getAttribute('aria-hidden') !== 'false') return;
   questsBody.innerHTML = '';

   if(questsView.screen === 'list'){
     if(questsHeaderTitle) questsHeaderTitle.textContent = 'Квесты';
     Object.keys(QUEST_LINES).forEach(lineId=>{
       if(lineId === 'event') return; // летний ивент завершён — не показываем в списке
       const line = QUEST_LINES[lineId];
       const st = getQuestState(lineId);
       const card = document.createElement('div');
       card.className = 'quest-line-card';
       const doneCount = Math.min(st.questIndex, line.quests.length);
       card.innerHTML = `
         <div class="quest-line-name">${line.name}</div>
         <div class="quest-line-desc">${line.description}</div>
         <div class="quest-line-progress">Пройдено квестов: ${doneCount}${line.quests.length ? ' / ' + line.quests.length : ''}</div>
       `;
       card.addEventListener('click', ()=>{
         questsView = { screen: 'detail', lineId };
         renderQuestsUI();
       });
       questsBody.appendChild(card);
     });
   } else if(questsView.screen === 'detail'){
     const lineId = questsView.lineId;
     const line = QUEST_LINES[lineId];
     const st = getQuestState(lineId);
     if(questsHeaderTitle) questsHeaderTitle.textContent = line.name;

     const backBtn = document.createElement('button');
     backBtn.className = 'action-btn muted-btn quest-back-btn';
     backBtn.textContent = '← Назад к линиям';
     backBtn.addEventListener('click', ()=>{
       questsView = { screen: 'list', lineId: null };
       renderQuestsUI();
     });
     questsBody.appendChild(backBtn);

     const quest = line.quests[st.questIndex];
     if(!quest){
       const placeholder = document.createElement('div');
       placeholder.className = 'quest-placeholder';
       placeholder.textContent = 'Не Завершено';
       questsBody.appendChild(placeholder);
       return;
     }

     const ready = isQuestReady(lineId, st.questIndex, quest);

     const tasksHtml = quest.tasks.map((task, taskIndex)=>{
       const progress = Math.min(task.target, getTaskProgress(lineId, st.questIndex, taskIndex));
       const pct = Math.round((progress / task.target) * 100);
       return `
         <div class="quest-task">
           <div class="quest-task-label">${task.label}</div>
           <div class="quest-progress-bar-wrap"><div class="quest-progress-bar-fill" style="width:${pct}%"></div></div>
           <div class="quest-progress-label">${progress} / ${task.target}</div>
         </div>
       `;
     }).join('');

     const card = document.createElement('div');
     card.className = 'quest-detail-card';
     card.innerHTML = `
       <div class="quest-detail-title">${quest.title}</div>
       ${tasksHtml}
       <div class="quest-reward-row">
         <button class="action-btn accent-btn quest-complete-btn"${ready ? '' : ' disabled'}>Завершить</button>
         <div class="quest-reward-text">Награда: ${quest.rewardText}</div>
       </div>
     `;
     questsBody.appendChild(card);
     card.querySelector('.quest-complete-btn').addEventListener('click', ()=> completeQuest(lineId));
   }
 }

 function completeQuest(lineId){
   const line = QUEST_LINES[lineId];
   const st = getQuestState(lineId);
   const quest = line.quests[st.questIndex];
   if(!quest) return;
   // Летний ивент завершён — прогресс, набранный ранее, остаётся как есть, но новые
   // квесты этой линии больше нельзя закрыть и получить награду.
   if(lineId === 'event'){
     briefResultMessage('Летний ивент завершён — эти квесты больше нельзя пройти', 2600);
     return;
   }
   if(!isQuestReady(lineId, st.questIndex, quest)) return;

   Object.keys(quest.reward || {}).forEach(potionId=>{
     if(POTIONS[potionId]){
       POTIONS[potionId].count = (POTIONS[potionId].count || 0) + quest.reward[potionId];
     }
   });
   if(quest.itemReward && quest.itemReward.id){
     ensureItem(quest.itemReward.id);
     const qty = quest.itemReward.qty || 1;
     inventory[quest.itemReward.id].count += qty;
     inventory[quest.itemReward.id].times += qty;
   }
   if(typeof quest.setBiomeChangerCooldownMs === 'number'){
     const oldCooldown = window._biomeChangerCooldownMs || (15 * 60 * 1000);
     window._biomeChangerCooldownMs = quest.setBiomeChangerCooldownMs;
     // if a cooldown is currently in progress, shrink the remaining wait by the same
     // proportion instead of leaving it stuck at the old, longer timer
     if(window._biomeChangerReadyAt){
       const now = Date.now();
       const remaining = window._biomeChangerReadyAt - now;
       if(remaining > 0){
         const shrunk = remaining * (quest.setBiomeChangerCooldownMs / oldCooldown);
         window._biomeChangerReadyAt = now + Math.min(shrunk, quest.setBiomeChangerCooldownMs);
       }
     }
   }
   renderInventory();
   briefResultMessage(`Квест выполнен! Награда: ${quest.rewardText}`, 2600);

   st.questIndex += 1;
   saveState();
   renderQuestsUI();
 }

