 function openBreweryGUI(){
   const breweryModal = document.getElementById('brewery-modal');
   const body = document.getElementById('brewery-craft-body');
   if(!breweryModal || !body) return;

   const entries = buildBreweryList();
   // register in the shared craftables cache too, so auto-craft can find these recipes
   // if the player ever turns it on for a potion
   if(!window._craftablesCache) window._craftablesCache = [];
   entries.forEach(entry=>{
     const idx = window._craftablesCache.findIndex(e => e && e.id === entry.id);
     if(idx >= 0) window._craftablesCache[idx] = entry;
     else window._craftablesCache.push(entry);
   });

   body.innerHTML = '';

   const section = document.createElement('div');
   section.id = 'brewery-potions-section';
   section.className = 'ws-section';
   const sectionHeader = document.createElement('div');
   sectionHeader.className = 'ws-intro';
   sectionHeader.innerHTML = `<b>${entries.length} рецепта</b><span>Положи ингредиенты, и котёл сварит зелье. Авто-крафт подбрасывает выпавшие ауры сам.</span>`;
   const sectionList = document.createElement('div');
   sectionList.className = 'craft-section-list ws-grid';
   section.appendChild(sectionHeader);
   section.appendChild(sectionList);
   body.appendChild(section);

   entries.forEach(entry=>{
     const card = document.createElement('div');
     card.className = 'craft-card ws-card';
     card.innerHTML = workshopHeadHTML(entry, entry.name);
     const header = card.querySelector('.ws-head');
     const toggleBtn = card.querySelector('.craft-toggle-btn');
     workshopRefreshStatus(card, entry);
     card.addEventListener('craft-progress', ()=> workshopRefreshStatus(card, entry));

     const collapsedArea = document.createElement('div');
     collapsedArea.className = 'ws-body';
     collapsedArea.style.display = 'none';
     card.appendChild(collapsedArea);

     function openCollapsed(){
       toggleBtn.textContent = '▴';
       collapsedArea.style.display = 'block';
       card.classList.add('ws-open');
       // build the heavy UI lazily, only once, on first expand
       if(collapsedArea.innerHTML.trim() === ''){
         const dyn = buildCraftIngredientsUI(entry);
         collapsedArea.appendChild(dyn);

         // auto-craft toggle row — copied from Кузница's createCraftCard so behaviour
         // matches exactly (only one craft may run auto-craft at a time, across BOTH buildings)
         const autoRow = document.createElement('div');
         autoRow.style.display = 'flex';
         autoRow.style.justifyContent = 'space-between';
         autoRow.style.alignItems = 'center';
         autoRow.style.marginTop = '8px';
         autoRow.style.gap = '12px';
         autoRow.innerHTML = `<div style="font-size:13px;color:var(--muted);flex:1">Авто-крафт — только для выпавших значений (авто-добавляет при выпадении)</div>`;

         const autoBtn = document.createElement('button');
         autoBtn.className = 'action-btn';
         autoBtn.style.padding = '10px 14px';
         autoBtn.style.fontSize = '15px';
         autoBtn.style.minWidth = '120px';
         autoBtn.style.borderRadius = '12px';
         const persisted = craftGetState(entry.id).autocraft === true;
         autoBtn.textContent = persisted ? 'Авто: Вкл' : 'Авто: Выкл';
         autoBtn.style.background = persisted ? '#0b6623' : '#777';
         autoBtn.style.color = '#fff';

         autoBtn.addEventListener('click', ()=>{
           const on = craftGetState(entry.id).autocraft !== true;
           if(on){
             Object.keys(craftState).forEach(k=>{
               if(k !== entry.id && craftState[k]) craftState[k].autocraft = false;
             });
           }
           craftGetState(entry.id).autocraft = on;
           autoBtn.textContent = on ? 'Авто: Вкл' : 'Авто: Выкл';
           autoBtn.style.background = on ? '#0b6623' : '#777';
           saveState();
           briefResultMessage(on ? `Авто-крафт включён: ${entry.name}` : `Авто-крафт выключен: ${entry.name}`, 1600);
         });

         autoRow.appendChild(autoBtn);
         collapsedArea.appendChild(autoRow);
       }
     }
     function closeCollapsed(){
       toggleBtn.textContent = '▾';
       collapsedArea.style.display = 'none';
       card.classList.remove('ws-open');
       workshopRefreshStatus(card, entry);
     }
     toggleBtn.addEventListener('click', (e)=>{
       e.stopPropagation();
       if(collapsedArea.style.display === 'block') closeCollapsed(); else openCollapsed();
     });
     header.addEventListener('click', (e)=>{ if(!e.target.closest('.craft-toggle-btn')) toggleBtn.click(); });

     sectionList.appendChild(card);
   });

   breweryModal.setAttribute('aria-hidden', 'false');
 }

