 // ============================================================
 // "Слова" — a Wordle-style minigame unlocked by codes that the dev generates
 // in the dev panel. Each code is a signed, obfuscated payload (word, attempts,
 // reward) — a player can't fabricate their own valid code without knowing the
 // hidden salt baked into the signature, and each code is redeemable exactly once.
 // ============================================================

 // Not real cryptography (this is all client-side JS, so nothing here can be made
 // truly unbreakable) — but this raises the bar far past "just read the code and
 // edit some numbers", which is the actual goal: a casual friend can't hand-craft
 // their own code without noticing this exists and reverse-engineering it.
 const WORDLE_SECRET_SALT = 'turtle-wordle-k9x2-hidden-salt-v1';

 function wordleHash(str){
   let hash = 5381;
   for(let i=0;i<str.length;i++){
     hash = ((hash << 5) + hash + str.charCodeAt(i)) >>> 0;
   }
   return hash.toString(36).padStart(8, '0');
 }

 function wordleObfuscate(str){
   let shifted = '';
   for(let i=0;i<str.length;i++){
     shifted += String.fromCharCode((str.charCodeAt(i) + ((i % 7) + 3)) % 256);
   }
   const reversed = shifted.split('').reverse().join('');
   return btoa(reversed).replace(/\+/g, '-').replace(/\//g, '_').replace(/=/g, '');
 }
 function wordleDeobfuscate(code){
   let b64 = code.replace(/-/g, '+').replace(/_/g, '/');
   while(b64.length % 4) b64 += '=';
   const reversed = atob(b64);
   const shifted = reversed.split('').reverse().join('');
   let str = '';
   for(let i=0;i<shifted.length;i++){
     let c = shifted.charCodeAt(i) - ((i % 7) + 3);
     while(c < 0) c += 256;
     str += String.fromCharCode(c % 256);
   }
   return str;
 }

 function generateWordleCode(payload){
   const json = JSON.stringify(payload);
   const payloadB64 = btoa(unescape(encodeURIComponent(json)));
   const sig = wordleHash(payloadB64 + WORDLE_SECRET_SALT);
   const combined = sig + '.' + payloadB64;
   return 'TRTL-' + wordleObfuscate(combined);
 }

 function decodeWordleCode(rawCode){
   try{
     const trimmed = (rawCode || '').trim();
     const prefix = 'TRTL-';
     if(trimmed.slice(0, prefix.length).toUpperCase() !== prefix) return null;
     const raw = trimmed.slice(prefix.length);
     const combined = wordleDeobfuscate(raw);
     const dotIdx = combined.indexOf('.');
     if(dotIdx === -1) return null;
     const sig = combined.slice(0, dotIdx);
     const payloadB64 = combined.slice(dotIdx + 1);
     const expectedSig = wordleHash(payloadB64 + WORDLE_SECRET_SALT);
     if(sig !== expectedSig) return null; // wrong/tampered/hand-crafted code
     const json = decodeURIComponent(escape(atob(payloadB64)));
     const payload = JSON.parse(json);
     if(!payload || typeof payload.w !== 'string' || !payload.w.length) return null;
     if(!Array.isArray(payload.rewards) || !payload.rewards.length) return null;
     return payload;
   }catch(e){
     return null;
   }
 }

 // General "Промокод" codes — a different prefix from Слова codes, same underlying
 // obfuscation/signature machinery. Can carry rewards, a weather change, and/or a buff
 // (existing potion or a fully custom one), any combination of which may be present.
 function generatePromoCode(payload){
   const json = JSON.stringify(payload);
   const payloadB64 = btoa(unescape(encodeURIComponent(json)));
   const sig = wordleHash(payloadB64 + WORDLE_SECRET_SALT);
   const combined = sig + '.' + payloadB64;
   return 'PROMO-' + wordleObfuscate(combined);
 }
 function decodePromoCode(rawCode){
   try{
     const trimmed = (rawCode || '').trim();
     const prefix = 'PROMO-';
     if(trimmed.slice(0, prefix.length).toUpperCase() !== prefix) return null;
     const raw = trimmed.slice(prefix.length);
     const combined = wordleDeobfuscate(raw);
     const dotIdx = combined.indexOf('.');
     if(dotIdx === -1) return null;
     const sig = combined.slice(0, dotIdx);
     const payloadB64 = combined.slice(dotIdx + 1);
     const expectedSig = wordleHash(payloadB64 + WORDLE_SECRET_SALT);
     if(sig !== expectedSig) return null; // wrong/tampered/hand-crafted code
     const json = decodeURIComponent(escape(atob(payloadB64)));
     const payload = JSON.parse(json);
     if(!payload || typeof payload.id !== 'string') return null;
     return payload;
   }catch(e){
     return null;
   }
 }

 // Applies everything a promo code carries: rewards, weather change, and/or a buff.
 function redeemPromoCode(payload){
   (payload.rewards || []).forEach(r=>{
     if(r.rt === 'aura' && ITEMS[r.ri]){
       ensureItem(r.ri);
       inventory[r.ri].count += r.rq;
       inventory[r.ri].times += r.rq;
       recordPulls(r.ri, r.rq);
     } else if(r.rt === 'potion' && POTIONS[r.ri]){
       POTIONS[r.ri].count = (POTIONS[r.ri].count || 0) + r.rq;
     } else if(r.rt === 'coins'){
       coins += r.rq;
       updateCoinDisplay(true);
     }
   });

   if(payload.weather && payload.weather.name){
     const ms = (typeof payload.weather.durationMin === 'number' && payload.weather.durationMin > 0)
       ? payload.weather.durationMin * 60000
       : undefined;
     try{ setWeatherNow(payload.weather.name, ms); }catch(e){}
   }

   // payload.buffs is the current (array) shape, letting a single code carry several
   // buffs at once; payload.buff (singular) is kept working for any codes generated
   // before this was added.
   const buffList = Array.isArray(payload.buffs) ? payload.buffs : (payload.buff ? [payload.buff] : []);
   buffList.forEach(buff=>{
     try{ applyPromoBuff(buff); }catch(e){}
   });

   renderInventory();
   updateTopStats();
   saveState();
   briefResultMessage('Промокод активирован!', 2400);
 }

 // Applies a buff carried by a promo code — either referencing an EXISTING potion's
 // effect (id points into POTIONS) or a fully custom one built in the dev panel.
 // Custom buffs are modeled as a synthetic POTIONS-like entry so they flow through all
 // the same machinery (activeEffects / spin-charges / icons) that real potions use.
 function applyPromoBuff(buff){
   if(buff.existingId && POTIONS[buff.existingId]){
     activatePotion(buff.existingId);
     return;
   }
   if(!buff.custom) return;
   const c = buff.custom;
   // Each custom buff gets its OWN id (derived from its name) rather than one shared
   // fixed id — a code carrying several custom buffs would otherwise have each one
   // overwrite the previous one's synthetic potion entry / activeEffects slot.
   const slug = (c.name || 'buff').toLowerCase().replace(/[^a-zа-я0-9]+/gi, '_').slice(0, 24);
   let buffId = 'promoCustom_' + slug;
   let n = 2;
   while(POTIONS[buffId] && POTIONS[buffId]._promoCustomOwner !== true){
     buffId = 'promoCustom_' + slug + '_' + n;
     n++;
   }
   POTIONS[buffId] = {
     id: buffId,
     name: c.name || 'Кастомный бафф',
     effectName: c.name || 'Кастомный бафф',
     desc: c.desc || '',
     color: c.color || '#ffb84d',
     iconColor: c.color || '#ffb84d',
     count: 0,
     duration: c.spinCount ? 0 : (c.durationMs || 60000),
     bonus: c.luckPercent || 0,
     speedBonus: c.speedPercent || 0,
     luckMultiplier: c.luckMultiplier || undefined,
     speedMultiplier: c.speedMultiplier || undefined,
     fixedLuck: c.fixedLuck || undefined,
     fixedSpeed: c.fixedSpeed || undefined,
     oneShot: !!c.spinCount,
     _promoCustomOwner: true
   };
   if(c.bonusSpinModifier){
     window._promoBonusSpinMultiplier = c.bonusSpinModifier;
   }
   if(c.spinCount){
     const total = addSpinCharge(buffId, c.spinCount);
     showSpinChargeIcon(buffId);
     recomputePotionSpeedMultiplier();
     briefResultMessage(`${POTIONS[buffId].name} забанкован (x${total}) — сработает на следующих прокрутках`, 2200);
   } else {
     activatePotion(buffId);
   }
 }

 function isWordleCodeUsed(id){
   try{
     const used = JSON.parse(localStorage.getItem('wordle_used_codes') || '[]');
     return used.indexOf(id) !== -1;
   }catch(e){ return false; }
 }
 function markWordleCodeUsed(id){
   try{
     const used = JSON.parse(localStorage.getItem('wordle_used_codes') || '[]');
     if(used.indexOf(id) === -1) used.push(id);
     localStorage.setItem('wordle_used_codes', JSON.stringify(used));
   }catch(e){}
 }

 const RU_KEYBOARD_ROWS = [
   ['Й','Ц','У','К','Е','Н','Г','Ш','Щ','З','Х','Ъ'],
   ['Ф','Ы','В','А','П','Р','О','Л','Д','Ж','Э'],
   ['ENTER','Я','Ч','С','М','И','Т','Ь','Б','Ю','BACK']
 ];

 let wordleSession = null; // { word, attempts, rt, ri, rq, id, guesses:[], current:'' }
 let wordleKeyState = {}; // letter -> 'correct'|'present'|'absent'

 function evaluateWordleGuess(guess, word){
   const result = new Array(guess.length).fill('absent');
   const counts = {};
   for(const c of word) counts[c] = (counts[c] || 0) + 1;
   for(let i=0;i<guess.length;i++){
     if(guess[i] === word[i]){
       result[i] = 'correct';
       counts[guess[i]]--;
     }
   }
   for(let i=0;i<guess.length;i++){
     if(result[i] === 'correct') continue;
     const c = guess[i];
     if(counts[c] > 0){
       result[i] = 'present';
       counts[c]--;
     }
   }
   return result;
 }

 function rewardLabel(session){
   const rewards = session.rewards || [];
   if(!rewards.length) return 'награда';
   return rewards.map(r=>{
     if(r.rt === 'coins') return `${r.rq} 🪙`;
     const meta = r.rt === 'aura' ? ITEMS[r.ri] : POTIONS[r.ri];
     return `${(meta && meta.name) || r.ri} x${r.rq}`;
   }).join(', ');
 }

 function grantWordleReward(session){
   (session.rewards || []).forEach(r=>{
     if(r.rt === 'aura' && ITEMS[r.ri]){
       ensureItem(r.ri);
       inventory[r.ri].count += r.rq;
       inventory[r.ri].times += r.rq;
       recordPulls(r.ri, r.rq);
     } else if(r.rt === 'potion' && POTIONS[r.ri]){
       POTIONS[r.ri].count = (POTIONS[r.ri].count || 0) + r.rq;
     } else if(r.rt === 'coins'){
       coins += r.rq;
       updateCoinDisplay(true);
     }
   });
   renderInventory();
   saveState();
 }

 function renderWordleGrid(){
   const grid = document.getElementById('wordle-grid');
   if(!grid || !wordleSession) return;
   grid.innerHTML = '';
   grid.style.setProperty('--wordle-cols', String(wordleSession.word.length));
   const availableWidth = Math.min(window.innerWidth * 0.88, 820);
   const cellSize = Math.max(24, Math.min(46, Math.floor(availableWidth / wordleSession.word.length) - 6));
   grid.style.setProperty('--wordle-cell-size', cellSize + 'px');
   for(let r=0;r<wordleSession.attempts;r++){
     const row = document.createElement('div');
     row.className = 'wordle-row';
     const guess = wordleSession.guesses[r];
     const isCurrent = (r === wordleSession.guesses.length && !wordleSession.finished);
     const letters = guess ? guess.letters : (isCurrent ? wordleSession.current.split('') : []);
     for(let c=0;c<wordleSession.word.length;c++){
       const cell = document.createElement('div');
       cell.className = 'wordle-cell';
       if(guess){
         cell.classList.add('wordle-' + guess.result[c]);
         cell.textContent = guess.letters[c];
       } else if(letters[c]){
         cell.classList.add('wordle-filled');
         cell.textContent = letters[c];
       }
       row.appendChild(cell);
     }
     grid.appendChild(row);
   }
 }

 function renderWordleKeyboard(){
   const kb = document.getElementById('wordle-keyboard');
   if(!kb) return;
   kb.innerHTML = '';
   RU_KEYBOARD_ROWS.forEach(rowLetters=>{
     const row = document.createElement('div');
     row.className = 'wordle-kb-row';
     rowLetters.forEach(letter=>{
       const key = document.createElement('button');
       key.type = 'button';
       key.className = 'wordle-key';
       if(letter === 'ENTER' || letter === 'BACK'){
         key.classList.add('wordle-key-wide');
         key.textContent = letter === 'ENTER' ? 'ВВОД' : '⌫';
       } else {
         key.textContent = letter;
         const state = wordleKeyState[letter];
         if(state) key.classList.add('wordle-key-' + state);
       }
       key.addEventListener('click', ()=> handleWordleKey(letter));
       row.appendChild(key);
     });
     kb.appendChild(row);
   });
 }

 function setWordleMessage(text){
   const el = document.getElementById('wordle-message');
   if(el) el.textContent = text || '';
 }

 function handleWordleKey(key){
   if(!wordleSession || wordleSession.finished) return;
   if(key === 'BACK'){
     wordleSession.current = wordleSession.current.slice(0, -1);
     renderWordleGrid();
     return;
   }
   if(key === 'ENTER'){
     if(wordleSession.current.length !== wordleSession.word.length){
       setWordleMessage(`Слово из ${wordleSession.word.length} букв`);
       return;
     }
     const guessLetters = wordleSession.current.split('');
     const result = evaluateWordleGuess(guessLetters, wordleSession.word.split(''));
     guessLetters.forEach((l, i)=>{
       const cur = wordleKeyState[l];
       const rank = { absent:0, present:1, correct:2 };
       if(!cur || rank[result[i]] > rank[cur]) wordleKeyState[l] = result[i];
     });
     wordleSession.guesses.push({ letters: guessLetters, result });
     const won = result.every(r => r === 'correct');
     wordleSession.current = '';

     if(won){
       wordleSession.finished = true;
       markWordleCodeUsed(wordleSession.id);
       grantWordleReward(wordleSession);
       setWordleMessage(`Разгадано! Награда: ${rewardLabel(wordleSession)}`);
       renderWordleGrid();
       renderWordleKeyboard();
       return;
     }
     if(wordleSession.guesses.length >= wordleSession.attempts){
       wordleSession.finished = true;
       markWordleCodeUsed(wordleSession.id);
       setWordleMessage(`Попытки закончились. Слово было: ${wordleSession.word}`);
       renderWordleGrid();
       renderWordleKeyboard();
       return;
     }
     setWordleMessage('');
     renderWordleGrid();
     renderWordleKeyboard();
     return;
   }
   // regular letter
   if(wordleSession.current.length < wordleSession.word.length){
     wordleSession.current += key;
     renderWordleGrid();
   }
 }

 const wordleModal = document.getElementById('wordle-modal');
 function openWordleGame(payload){
   wordleSession = {
     word: String(payload.w).toUpperCase(),
     attempts: Math.max(1, Math.floor(Number(payload.a) || 6)),
     rewards: Array.isArray(payload.rewards) ? payload.rewards : [],
     id: payload.id,
     guesses: [],
     current: '',
     finished: false
   };
   wordleKeyState = {};
   setWordleMessage('');
   renderWordleGrid();
   renderWordleKeyboard();
   if(wordleModal) wordleModal.setAttribute('aria-hidden', 'false');
 }
 function closeWordleGame(){
   if(wordleModal) wordleModal.setAttribute('aria-hidden', 'true');
 }

 document.addEventListener('keydown', (e)=>{
   if(!wordleModal || wordleModal.getAttribute('aria-hidden') !== 'false') return;
   if(!wordleSession || wordleSession.finished) return;
   if(e.key === 'Enter'){ handleWordleKey('ENTER'); return; }
   if(e.key === 'Backspace'){ handleWordleKey('BACK'); return; }
   const letter = e.key.toUpperCase();
   if(/^[А-ЯЁ]$/.test(letter)) handleWordleKey(letter);
 });

 const wordleCloseBtn = document.getElementById('wordle-close');
 if(wordleCloseBtn) wordleCloseBtn.addEventListener('click', closeWordleGame);
 if(wordleModal){
   wordleModal.addEventListener('click', (e)=>{ if(e.target === wordleModal) closeWordleGame(); });
 }

 // "Слова" button + code-entry modal
 const wordsBtn = document.getElementById('words-btn');
 const wordsCodeModal = document.getElementById('words-code-modal');
 const wordsCodeClose = document.getElementById('words-code-close');
 const wordsCodeInput = document.getElementById('words-code-input');
 const wordsCodeError = document.getElementById('words-code-error');
 const wordsCodeSubmit = document.getElementById('words-code-submit');

 function openWordsCodeModal(){
   if(wordsCodeInput) wordsCodeInput.value = '';
   if(wordsCodeError) wordsCodeError.textContent = '';
   if(wordsCodeModal) wordsCodeModal.setAttribute('aria-hidden', 'false');
 }
 function closeWordsCodeModal(){
   if(wordsCodeModal) wordsCodeModal.setAttribute('aria-hidden', 'true');
 }
 if(wordsBtn) wordsBtn.addEventListener('click', openWordsCodeModal);

 // UI-hide toggle: hides every other button on the page (see CSS) so the player can
 // enjoy a theme without any chrome in the way; click again to bring it all back.
 const uiToggleBtn = document.getElementById('ui-toggle-btn');
 if(uiToggleBtn){
   uiToggleBtn.addEventListener('click', ()=>{
     const hidden = document.body.classList.toggle('ui-hidden');
     uiToggleBtn.textContent = hidden ? '🙈' : '👁️';
     uiToggleBtn.setAttribute('aria-label', hidden ? 'Показать интерфейс' : 'Скрыть интерфейс');
   });
 }
 if(wordsCodeClose) wordsCodeClose.addEventListener('click', closeWordsCodeModal);
 if(wordsCodeModal){
   wordsCodeModal.addEventListener('click', (e)=>{ if(e.target === wordsCodeModal) closeWordsCodeModal(); });
 }
 if(wordsCodeSubmit){
   wordsCodeSubmit.addEventListener('click', ()=>{
     const raw = (wordsCodeInput && wordsCodeInput.value) || '';
     const trimmed = raw.trim();

     if(trimmed.toUpperCase().startsWith('PROMO-')){
       const promoPayload = decodePromoCode(trimmed);
       if(!promoPayload){
         if(wordsCodeError) wordsCodeError.textContent = 'Код неверный или повреждён.';
         return;
       }
       if(isWordleCodeUsed(promoPayload.id)){
         if(wordsCodeError) wordsCodeError.textContent = 'Этот код уже использован.';
         return;
       }
       markWordleCodeUsed(promoPayload.id);
       closeWordsCodeModal();
       redeemPromoCode(promoPayload);
       return;
     }

     const payload = decodeWordleCode(trimmed);
     if(!payload){
       if(wordsCodeError) wordsCodeError.textContent = 'Код неверный или повреждён.';
       return;
     }
     if(isWordleCodeUsed(payload.id)){
       if(wordsCodeError) wordsCodeError.textContent = 'Этот код уже использован.';
       return;
     }
     closeWordsCodeModal();
     openWordleGame(payload);
   });
 }
 if(wordsCodeInput){
   wordsCodeInput.addEventListener('keydown', (e)=>{
     if(e.key === 'Enter') wordsCodeSubmit.click();
   });
 }

 if(closeCraftBtn){
   closeCraftBtn.addEventListener('click', ()=> {
     craftModal.setAttribute('aria-hidden','true');
     // hide ingredients area when closing
     const craftIngredientsEl = document.querySelector('.craft-ingredients');
     if(craftIngredientsEl) craftIngredientsEl.setAttribute('hidden','');
   });
 }
 if(craftModal){
   craftModal.addEventListener('click', (e)=>{
     if(e.target === craftModal){
       craftModal.setAttribute('aria-hidden','true');
       const craftIngredientsEl = document.querySelector('.craft-ingredients');
       if(craftIngredientsEl) craftIngredientsEl.setAttribute('hidden','');
     }
   });
}

// ---- Start menu ----
// Shown on load; button reads "Продолжить" if a save already exists, "Начать" otherwise.
// The game state has already loaded in the background regardless — this is just a welcome gate.
(function initStartMenu(){
  const startMenu = document.getElementById('start-menu');
  const startBtn = document.getElementById('start-menu-btn');
  if(!startMenu || !startBtn) return;

  let hasSave = false;
  try{
    for(let i=1;i<=MAX_SAVE_SLOTS;i++){
      if(localStorage.getItem(getSaveKey(i))){ hasSave = true; break; }
    }
  }catch(e){}

  startBtn.textContent = hasSave ? 'Продолжить' : 'Начать';

  startBtn.addEventListener('click', ()=>{
    startMenu.classList.add('hide');
    setTimeout(()=>{ try{ startMenu.remove(); }catch(e){} }, 420);
  });
})();

// Extra safety net: some mobile browsers silently discard/reload a backgrounded tab to
// free memory — from the user's perspective that looks like "I just switched apps and
// came back", not a reload, but the JS state (and craftables cache) starts fresh either
// way. Re-check whenever the tab becomes visible again so auto-craft never silently stops.
document.addEventListener('visibilitychange', ()=>{
  if(document.visibilityState === 'visible'){
    try{
      if(!window._craftablesCache || !window._craftablesCache.length) buildCraftablesList();
    }catch(e){}
    // resume decorative rendering
    document.body.classList.remove('tab-hidden');
    try{ applyWeatherTheme(true); }catch(e){}
    if(!window._weatherThemeInterval){
      window._weatherThemeInterval = setInterval(()=>{ applyWeatherTheme(); }, 1000);
    }
    // Rebuild the current theme's decorations fresh. This matters because merely
    // CSS-pausing animations (below) never stopped the particle/ember/spark spawn
    // timers themselves — they kept firing the whole time the tab was hidden (throttled
    // by the browser, but still firing), quietly piling up DOM elements with their
    // animations frozen. Coming back to the tab meant a sudden burst of queued removals
    // and simultaneously-resuming animations, which is the "much slower" the tab felt
    // right after switching back. Rebuilding from a clean slate avoids that pile-up.
    try{ applyThemeForItem(activeThemeId); }catch(e){}
  } else {
    // Tab is in the background: suspend everything that only exists to look nice.
    // Game logic (spins, auto-collector, effect timers, saving) is deliberately NOT
    // touched — only rendering work stops, which is what actually burns CPU when the
    // window isn't even visible.
    document.body.classList.add('tab-hidden');
    if(window._weatherThemeInterval){
      clearInterval(window._weatherThemeInterval);
      window._weatherThemeInterval = null;
    }
    // Fully tear down the active theme's decorations — this clears every particle/ember/
    // spark spawn interval and mousemove listener the theme set up, not just their CSS
    // animations. Nothing new gets created while the tab is hidden.
    try{ applyThemeForItem(null); }catch(e){}
  }
});

// ---- Настройки: графика фона, музыка тем, звуки выпадения ----
(function(){
  const gfxSel = document.getElementById('gfx-mode');
  if(gfxSel){
    gfxSel.value = GFX.mode;
    gfxSel.addEventListener('change', ()=> GFX.setMode(gfxSel.value));
  }
  const bindRange = (inputId, labelId, get, set)=>{
    const r = document.getElementById(inputId), l = document.getElementById(labelId);
    if(!r) return;
    r.value = String(Math.round(get() * 100));
    if(l) l.textContent = r.value + '%';
    r.addEventListener('input', ()=>{ set(Number(r.value) / 100); if(l) l.textContent = r.value + '%'; });
  };
  bindRange('music-volume', 'music-volume-val', ()=> AMB.musicVolume, (v)=> AMB.setMusicVolume(v));
  bindRange('sfx-volume', 'sfx-volume-val', ()=> AMB.sfxVolume, (v)=>{ AMB.setSfxVolume(v); });
  bindRange('weather-volume', 'weather-volume-val', ()=> weatherVolume(), (v)=> setWeatherVolume(v));
  // per-class drop sounds
  const dsWrap = document.getElementById('drop-sound-classes');
  if(dsWrap){
    DROP_SOUND_CLASSES.forEach(cls=>{
      const meta = RARITY_CLASS_META[cls];
      const label = cls === 'incredible' ? 'Невероятный' : meta.name.charAt(0) + meta.name.slice(1).toLowerCase();
      const b = document.createElement('button');
      b.type = 'button'; b.className = 'ds-chip'; b.textContent = label;
      b.style.setProperty('--chip', meta.color);
      const sync = ()=>{ const on = dropSoundOn(cls); b.setAttribute('aria-pressed', on ? 'true' : 'false'); b.title = on ? 'Звук включён' : 'Без звука'; };
      b.addEventListener('click', ()=>{ setDropSound(cls, !dropSoundOn(cls)); sync(); });
      sync();
      dsWrap.appendChild(b);
    });
  }
  // what's playing: a chip that fades in when a theme's track starts, and a line in settings
  const np = document.getElementById('now-playing');
  const npSet = document.getElementById('settings-now-playing');
  let npTimer = null;
  window.addEventListener('amb-track', (e)=>{
    const d = e.detail || {};
    if(npSet) npSet.textContent = d.id ? `${d.name}${d.genre ? ' (' + d.genre + ')' : ''}` : 'Тишина';
    if(!np || !d.id || d.preview) return;
    np.innerHTML = `<span class="np-note"><svg viewBox="0 0 24 24" width="15" height="15" fill="currentColor" aria-hidden="true"><path d="M9 17.5a3 3 0 1 1-2-2.83V5.5l11-2v11.5a3 3 0 1 1-2-2.83V7.3l-7 1.27z"/></svg></span><span><b>${d.name}</b><small>${d.genre || ''}</small></span>`;
    np.classList.add('show');
    try{ rgSchedule(420); }catch(e){}
    clearTimeout(npTimer);
    npTimer = setTimeout(()=> np.classList.remove('show'), 5200);
  });
  // warm the effect buffers once the player has touched the page
  const warm = ()=>{
    window.removeEventListener('pointerdown', warm);
    ['0611.mp3', '0611_1_.mp3', '0611_2_ (1).mp3', 'Big cinematic impact Sound Effect 4.mp3', 'mega-drop-impact.wav', 'very-good-impact.mp3'].forEach(u=>{ try{ AMB.preload(u); }catch(e){} });
  };
  window.addEventListener('pointerdown', warm, { passive:true });
})();


window.__prkSave = ()=>{ try{ saveState(); }catch(e){} };
